INSERT INTO `SERVMASK_PREFIX_fluentform_submissions` VALUES (2,1,2,'{\"__fluent_form_embded_post_id\":\"580\",\"_fluentform_1_fluentformnonce\":\"34dad53c03\",\"_wp_http_referer\":\"\\/contact\\/\",\"names\":{\"first_name\":\"Joanna Holden\"},\"numeric_field\":\"6811985902\",\"email\":\"joannaholden1981@gmail.com\",\"message\":\"Hi there,\\r\\n\\r\\nWe run a Youtube growth service, where we can increase your subscriber count safely and practically. \\r\\n\\r\\n- Guaranteed: We guarantee to gain you 400+ new subscribers each month.\\r\\n- Real, human subscribers who subscribe because they are interested in your channel\\/videos.\\r\\n- Safe: All actions are done, without using any automated tasks \\/ bots.\\r\\n\\r\\nIf you are interested then we can discuss further.\\r\\n\\r\\nKind Regards,\\r\\nJoanna\"}','https://furbuddy.xyz/contact/',0,'unread',0,'Vivalidi','Apple','191.102.167.43',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-02-19 07:30:44','2026-02-19 07:30:44');
