INSERT INTO `SERVMASK_PREFIX_fluentform_submissions` VALUES (9,1,9,'{\"__fluent_form_embded_post_id\":\"580\",\"_fluentform_1_fluentformnonce\":\"5e61cd84ca\",\"_wp_http_referer\":\"\\/contact\\/\",\"names\":{\"first_name\":\"RaymondMoogs\"},\"numeric_field\":\"87348927659\",\"email\":\"no.reply.anthonvthomas@gmail.com\",\"message\":\"Wassup? furbuddy.xyz \\r\\n \\r\\nDid you know that it is possible to send proposals consequently legally? \\r\\nWhen such business proposals are sent, no personal data is used, and messages are sent to forms specifically designed to receive messages and appeals securely. Contact Form messages are usually not sent to spam, since they are viewed as important. \\r\\nThere is now no cost to you to try out our service. \\r\\nYou can trust us to send up to 50,000 messages. \\r\\n \\r\\nThe cost of sending one million messages is $59. \\r\\n \\r\\nThis message was automatically generated. \\r\\n \\r\\nContact us. \\r\\nTelegram - https:\\/\\/t.me\\/FeedbackFormEU \\r\\nWhatsApp - +375259112693 \\r\\nWhatsApp  https:\\/\\/wa.me\\/+375259112693 \\r\\nWe only use chat for communication.\"}','https://furbuddy.xyz/contact/',0,'unread',0,'Chrome','Windows','37.19.223.109',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-03-08 02:38:42','2026-03-08 02:38:42');
INSERT INTO `SERVMASK_PREFIX_fluentform_submissions` VALUES (10,1,10,'{\"__fluent_form_embded_post_id\":\"580\",\"_fluentform_1_fluentformnonce\":\"5e61cd84ca\",\"_wp_http_referer\":\"\\/contact\\/\",\"names\":{\"first_name\":\"Nancy\"},\"numeric_field\":\"8468088599\",\"email\":\"nancy.99seosolutionworld@gmail.com\",\"message\":\"Hello http:\\/\\/furbuddy.xyz,\\r\\n\\r\\nYour website has potential, but currently it’s missing strong visibility on search engines like Google and Yahoo.\\r\\n\\r\\nWe can optimize it to improve rankings and organic traffic.\\r\\n\\r\\nShare your target keywords and locations, and I’ll send detailed SEO packages.\\r\\n\\r\\nBest regards,\\r\\nNancy\"}','https://furbuddy.xyz/contact/',0,'unread',0,'Chrome','Linux','182.69.178.196',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-03-09 15:40:04','2026-03-09 15:40:04');
