INSERT INTO `SERVMASK_PREFIX_options` VALUES (51089,'_transient_pum_feature_announcements_v2_es_mx','a:6:{i:0;a:10:{s:4:\"code\";s:30:\"pm_tip_chrome_debug_tools_2026\";s:4:\"type\";s:4:\"info\";s:8:\"category\";s:14:\"recommendation\";s:5:\"title\";s:28:\"Test popups while logged out\";s:7:\"message\";s:159:\"Use the free <strong>Popup Maker Debug Tools</strong> Chrome extension to test and troubleshoot popups from the front end—even while logged out of WordPress.\";s:8:\"subtitle\";s:19:\"free debugging tool\";s:4:\"icon\";s:11:\"admin-tools\";s:8:\"priority\";i:84;s:11:\"dismissible\";b:1;s:7:\"actions\";a:2:{i:0;a:6:{s:4:\"text\";s:21:\"View Chrome extension\";s:4:\"type\";s:4:\"link\";s:6:\"action\";s:0:\"\";s:4:\"href\";s:97:\"https://chromewebstore.google.com/detail/popup-maker-debug-tools/hhkgmkibaalfkkndobkckdopemgioago\";s:7:\"primary\";b:1;s:8:\"external\";b:1;}i:1;a:3:{s:4:\"text\";s:9:\"Descartar\";s:4:\"type\";s:6:\"action\";s:6:\"action\";s:7:\"dismiss\";}}}i:1;a:10:{s:4:\"code\";s:33:\"pm_upsell_advanced_analytics_2026\";s:4:\"type\";s:4:\"info\";s:8:\"category\";s:14:\"recommendation\";s:5:\"title\";s:36:\"See what is driving your conversions\";s:7:\"message\";s:212:\"You have enough conversion activity to spot real trends. <strong>Advanced Analytics in Popup Maker Pro</strong> adds visual reports, URL performance, campaign attribution, filters, and deeper conversion insights.\";s:8:\"subtitle\";s:33:\"based on your conversion activity\";s:4:\"icon\";s:10:\"chart-area\";s:8:\"priority\";i:81;s:11:\"dismissible\";b:1;s:7:\"actions\";a:2:{i:0;a:6:{s:4:\"text\";s:26:\"Explore Advanced Analytics\";s:4:\"type\";s:4:\"link\";s:6:\"action\";s:0:\"\";s:4:\"href\";s:110:\"https://wppopupmaker.com/pricing/?utm_source=pm-notifications&utm_medium=panel&utm_campaign=advanced-analytics\";s:7:\"primary\";b:1;s:8:\"external\";b:1;}i:1;a:4:{s:4:\"text\";s:7:\"Not now\";s:4:\"type\";s:6:\"action\";s:6:\"action\";s:7:\"dismiss\";s:7:\"expires\";s:7:\"30 days\";}}}i:2;