INSERT INTO `SERVMASK_PREFIX_posts` VALUES (865,1,'2026-04-02 18:40:14','2026-04-03 00:40:14','Brinda a tu mascota el descanso que merece con esta cama suave y acolchonada.<br data-start=\"489\" data-end=\"492\" />Su diseño cómodo y material agradable proporciona un espacio perfecto para dormir y relajarse.<br data-start=\"588\" data-end=\"591\" />Ideal para perros y gatos de gran tamaño.','Cama suave y acolchonada para mascotas','El lugar favorito de descanso de tus consentidos','publish','open','closed','','cama-suave-y-acolchonada-para-mascotas','','','2026-04-02 18:40:14','2026-04-03 00:40:14','',0,'https://furbuddy.xyz/?post_type=product&#038;p=865',0,'product','',0);
