INSERT INTO `SERVMASK_PREFIX_posts` VALUES (942,1,'2026-04-03 22:31:34','2026-04-04 04:31:34','Juguete interactivo para perros dedicado para entretener y estimular su curiosidad a la vez que se le recompensa con comida para incentivar a que continúe, hecho con materiales resistentes y de tamaño adecuado para cualquier raza.','Comedero interactivo para perros adipets','','publish','open','closed','','juguete-interactivo-para-perros-adipets','','','2026-04-22 19:21:48','2026-04-23 01:21:48','',0,'https://furbuddy.xyz/?post_type=product&#038;p=942',0,'product','',1);
