INSERT INTO `SERVMASK_PREFIX_posts` VALUES (945,1,'2026-04-03 22:36:34','2026-04-04 04:36:34','Plato con distintas secciones que permiten que el perro las mueva para conseguir su alimento, los mantiene entretenidos a la vez que los estimula e incentiva a buscar más comida. Libre de materiales tóxicos y resistente para aquellos que les gusta morder.','Plato con puzzle para perros','','publish','open','closed','','plato-con-puzzle-para-perros','','','2026-04-03 22:36:34','2026-04-04 04:36:34','',0,'https://furbuddy.xyz/?post_type=product&#038;p=945',0,'product','',0);
