INSERT INTO `SERVMASK_PREFIX_posts` VALUES (1553,5,'2026-04-22 20:10:48','2026-04-23 02:10:48','<!-- wp:group {\"metadata\":{\"categories\":[\"blocksy\"],\"patternName\":\"blocksy/pattern-7\",\"name\":\"Blocksy - Hero Section\"},\"align\":\"full\",\"backgroundColor\":\"white\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull has-white-background-color has-background\"><!-- wp:paragraph {\"align\":\"center\",\"textColor\":\"palette-color-3\"} -->\n<p class=\"has-text-align-center has-palette-color-3-color has-text-color\">Preguntas frecuentes</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":1,\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"800\",\"lineHeight\":\"1.2\"},\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"20px\"}},\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|palette-color-2\"}}}},\"textColor\":\"palette-color-2\",\"fontSize\":\"xx-large\"} -->\n<h1 class=\"wp-block-heading has-text-align-center has-palette-color-2-color has-text-color has-link-color has-xx-large-font-size\" style=\"margin-top:0;margin-bottom:20px;font-style:normal;font-weight:800;line-height:1.2\">¿En que podemos ayudarte?</h1>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|black\"}}},\"spacing\":{\"margin\":{\"bottom\":\"var:preset|spacing|60\"}}},\"textColor\":\"black\"} -->\n<p class=\"has-text-align-center has-black-color has-text-color has-link-color\" style=\"margin-bottom:var(--wp--preset--spacing--60)\">Encuentra respuestas rápidas sobre tus pedidos, envíos y el cuidado de tu mejor amigo.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"style\":{\"spacing\":{\"blockGap\":{\"left\":\"var:preset|spacing|50\"},\"margin\":{\"bottom\":\"var:preset|spacing|80\"}}},\"layout\":{\"type\":\"flex\",\"verticalAlignment\":\"center\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\" style=\"margin-bottom:var(--wp--preset--spacing--80)\"><!-- wp:button {\"textColor\":\"white\",\"style\":{\"border\":{\"radius\":\"8px\"},\"spacing\":{\"padding\":{\"left\":\"25px\",\"right\":\"25px\",\"top\":\"15px\",\"bottom\":\"15px\"}},\"typography\":{\"fontSize\":\"18px\"},\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|white\"}}},\"color\":{\"background\":\"#7eb650\"}}} -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link has-white-color has-text-color has-background has-link-color has-custom-font-size wp-element-button\" href=\"https://furbuddy.xyz/tienda/\" style=\"border-radius:8px;background-color:#7eb650;padding-top:15px;padding-right:25px;padding-bottom:15px;padding-left:25px;font-size:18px\">Tienda</a></div>\n<!-- /wp:button -->\n\n<!-- wp:button {\"backgroundColor\":\"white\",\"className\":\"is-style-outline\",\"style\":{\"border\":{\"radius\":\"8px\",\"color\":\"#7eb650\",\"width\":\"2px\"},\"spacing\":{\"padding\":{\"left\":\"25px\",\"right\":\"25px\",\"top\":\"13px\",\"bottom\":\"13px\"}},\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"400\",\"fontSize\":\"18px\"},\"elements\":{\"link\":{\"color\":{\"text\":\"#7eb650\"}}},\"color\":{\"text\":\"#7eb650\"}}} -->\n<div class=\"wp-block-button is-style-outline\"><a class=\"wp-block-button__link has-white-background-color has-text-color has-background has-link-color has-border-color has-custom-font-size wp-element-button\" href=\"https://furbuddy.xyz\" style=\"border-color:#7eb650;border-width:2px;border-radius:8px;color:#7eb650;padding-top:13px;padding-right:25px;padding-bottom:13px;padding-left:25px;font-size:18px;font-style:normal;font-weight:400\">Inicio</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->\n\n<!-- wp:columns {\"align\":\"wide\",\"style\":{\"border\":{\"radius\":\"20px\"},\"spacing\":{\"padding\":{\"top\":\"50px\",\"bottom\":\"50px\",\"left\":\"50px\",\"right\":\"50px\"},\"blockGap\":{\"top\":\"var:preset|spacing|70\",\"left\":\"var:preset|spacing|70\"}}},\"backgroundColor\":\"palette-color-2\"} -->\n<div class=\"wp-block-columns alignwide has-palette-color-2-background-color has-background\" style=\"border-radius:20px;padding-top:50px;padding-right:50px;padding-bottom:50px;padding-left:50px\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"lineHeight\":\"1\",\"fontStyle\":\"normal\",\"fontWeight\":\"800\",\"fontSize\":\"40px\"},\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|white\"}}},\"spacing\":{\"margin\":{\"bottom\":\"30px\"}}},\"textColor\":\"white\"} -->\n<p class=\"has-text-align-center has-white-color has-text-color has-link-color\" style=\"margin-bottom:30px;font-size:40px;font-style:normal;font-weight:800;line-height:1\">01</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|white\"}}},\"typography\":{\"fontSize\":\"20px\"},\"spacing\":{\"margin\":{\"bottom\":\"10px\",\"top\":\"0px\"}}},\"textColor\":\"white\"} -->\n<h2 class=\"wp-block-heading has-text-align-center has-white-color has-text-color has-link-color\" style=\"margin-top:0px;margin-bottom:10px;font-size:20px\">Contacta con nosotros</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"spacing\":{\"margin\":{\"bottom\":\"30px\"}},\"elements\":{\"link\":{\"color\":{\"text\":\"#ffffffba\"}}},\"color\":{\"text\":\"#ffffffba\"}}} -->\n<p class=\"has-text-align-center has-text-color has-link-color\" style=\"color:#ffffffba;margin-bottom:30px\">Recibe atención al cliente personalizada con cualquier duda que tengas.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:stackable/button-group {\"uniqueId\":\"0a93bb3\",\"contentAlign\":\"center\"} -->\n<div class=\"wp-block-stackable-button-group stk-block-button-group stk-block stk-0a93bb3\" data-block-id=\"0a93bb3\"><div class=\"stk-row stk-inner-blocks has-text-align-center stk-block-c