\":\"10px\"},\"spacing\":{\"padding\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"20px\",\"right\":\"20px\"}}},\"backgroundColor\":\"white\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group has-white-background-color has-background\" style=\"border-radius:10px;padding-top:20px;padding-right:20px;padding-bottom:20px;padding-left:20px\"><!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group\"><!-- wp:group {\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:image {\"id\":1511,\"width\":\"40px\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"style\":{\"border\":{\"radius\":\"100px\"},\"spacing\":{\"margin\":{\"bottom\":\"10px\"}}}} -->\n<figure class=\"wp-block-image size-full is-resized has-custom-border\" style=\"margin-bottom:10px\"><img src=\"https://furbuddy.xyz/wp-content/uploads/2026/04/imagen_2026-04-22_193815824.png\" alt=\"\" class=\"wp-image-1511\" style=\"border-radius:100px;width:40px\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group -->\n\n<!-- wp:stackable/text {\"uniqueId\":\"9cadbab\",\"blockMargin\":{\"bottom\":14},\"contentAlign\":\"left\"} -->\n<div class=\"wp-block-stackable-text stk-block-text stk-block stk-9cadbab\" data-block-id=\"9cadbab\"><style>.stk-9cadbab {margin-bottom:14px !important;}</style><p class=\"stk-block-text__text has-text-align-left\">Gabriela Morales</p></div>\n<!-- /wp:stackable/text --></div>\n<!-- /wp:group -->\n\n<!-- wp:heading {\"level\":1,\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|black\"}}},\"spacing\":{\"margin\":{\"top\":\"0\"}},\"typography\":{\"fontSize\":\"16px\"}},\"textColor\":\"black\"} -->\n<h1 class=\"wp-block-heading has-black-color has-text-color has-link-color\" style=\"margin-top:0;font-size:16px\">\"La ropa que compré en Furbuddy es de buena calidad, a mi perrita no le molesta cuando se la pongo todos los días a la hora de salir\"</h1>\n<!-- /wp:heading --></div>\n<!-- /wp:group --></div></div>\n<!-- /wp:cover --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:stackable/divider {\"uniqueId\":\"e907894\"} -->\n<div class=\"wp-block-stackable-divider stk-block-divider stk-block stk-e907894\" data-block-id=\"e907894\"><hr class=\"stk-block-divider__hr\"/></div>\n<!-- /wp:stackable/divider --></div>\n<!-- /wp:group -->\n\n<!-- wp:stackable/heading {\"uniqueId\":\"a5f98b0\",\"blockMargin\":{\"bottom\":\"\"}} -->\n<div class=\"wp-block-stackable-heading stk-block-heading stk-block-heading--v2 stk-block stk-a5f98b0\" id=\"algunas-resenas-sobre-juguetes-populares\" data-block-id=\"a5f98b0\"><h2 class=\"stk-block-heading__text\">Algunas reseñas sobre juguetes populares</h2></div>\n<!-- /wp:stackable/heading -->\n\n<!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|60\",\"left\":\"var:preset|spacing|60\"}}}} -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:cover {\"url\":\"https://furbuddy.xyz/wp-content/uploads/2026/04/imagen_2026-04-22_191438928.png\",\"id\":1465,\"dimRatio\":0,\"isUserOverlayColor\":true,\"minHeight\":650,\"contentPosition\":\"bottom center\",\"isDark\":false,\"sizeSlug\":\"full\",\"style\":{\"border\":{\"radius\":\"20px\"},\"spacing\":{\"padding\":{\"top\":\"30px\",\"bottom\":\"30px\",\"left\":\"30px\",\"right\":\"30px\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-cover is-light has-custom-content-position is-position-bottom-center\" style=\"border-radius:20px;padding-top:30px;padding-right:30px;padding-bottom:30px;padding-left:30px;min-height:650px\"><img class=\"wp-block-cover__image-background wp-image-1465 size-full\" alt=\"\" src=\"https://furbuddy.xyz/wp-content/uploads/2026/04/imagen_2026-04-22_191438928.png\" data-object-fit=\"cover\"/><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim-0 has-background-dim\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:stackable/image {\"uniqueId\":\"8ced93a\",\"imageUrl\":\"https://furbuddy.xyz/wp-content/uploads/2026/04/imagen_2026-04-22_191753801.png\",\"imageId\":1473,\"imageWidthAttribute\":1200,\"imageHeightAttribute\":900} -->\n<div class=\"wp-block-stackable-image stk-block-image stk-block stk-8ced93a\" data-block-id=\"8ced93a\"><figure><span class=\"stk-img-wrapper stk-image--shape-stretch\"><img class=\"stk-img wp-image-1473\" src=\"https://furbuddy.xyz/wp-content/uploads/2026/04/imagen_2026-04-22_191753801.png\" width=\"1200\" height=\"900\"/></span></figure></div>\n<!-- /wp:stackable/image -->\n\n<!-- wp:group {\"style\":{\"border\":{\"radius\":\"10px\"},\"spacing\":{\"padding\":{\"top\":\"30px\",\"bottom\":\"30px\",\"left\":\"30px\",\"right\":\"30px\"}}},\"backgroundColor\":\"white\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group has-white-background-color has-background\" style=\"border-radius:10px;padding-top:30px;padding-right:30px;padding-bottom:30px;padding-left:30px\"><!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group\"><!-- wp:group {\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:image {\"id\":1542,\"width\":\"40px\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"is-style-rounded\",\"style\":{\"border\":{\"radius\":\"100px\"},\"spacing\":{\"margin\":{\"bottom\":\"10px\"}}}} -->\n<figure class=\"wp-block-image size-full is-resized has-custom-border is-style-rounded\" style=\"margin-bottom:10px\"><img src=\"https://furbuddy.xyz/wp-content/uploads/2026/04/imagen_2026-04-22_195830077.png\" alt=\"\" class=\"wp-image-1542\" style=\"border-radius:100px;width:40px\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group -->\n\n<!-- wp:stackable/text {\"uniqueId\":\"b24258c\",\"blockMargin\":{\"bottom\":14},\"contentAlign\":\"left\"} -->\n<div class=\"wp-block-stackable-text stk-block-text stk-block stk-b24258c\" data-block-id=\"b24258c\"><style>.stk-b24258c {margin-bottom:14px !important;}</style><p class=\"stk-block-text__text has-text-align-left\"><strong>Juan Carlos Bodoque</strong></p></div>\n<!-- /wp:stackable/text --></div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"margin\":{\"bottom\":\"30px\"}},\"elements\":{\"link\":{\"color\":{\"text\":\"#000000a8\"}}},\"color\":{\"text\":\"#000000a8\"}}} -->\n<p class=\"has-text-color has-link-color\" style=\"color:#000000a8;margin-bottom:30px\">\"He comprado juguetes para que mi perro muerda y halle de ellos, es bastante fuerte y aún así han durado mucho\"</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div></div>\n<!-- /wp:cover --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:cover {\"url\":\"https://furbuddy.xyz/wp-content/uploads/2026/04/imagen_2026-04-22_191513341.png\",\"id\":1467,\"dimRatio\":0,\"isUserOverlayColor\":true,\"minHeight\":650,\"contentPosition\":\"bottom center\",\"isDark\":false,\"sizeSlug\":\"full\",\"style\":{\"border\":{\"radius\":\"20px\"},\"spacing\":{\"padding\":{\"top\":\"30px\",\"bottom\":\"30px\",\"left\":\"30px\",\"right\":\"30px\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-cover is-light has-custom-content-position is-position-bottom-center\" style=\"border-radius:20px;padding-top:30px;padding-right:30px;padding-bottom:30px;padding-left:30px;min-height:650px\"><img class=\"wp-block-cover__image-background wp-image-1467 size-full\" alt=\"\" src=\"https://furbuddy.xyz/wp-content/uploads/2026/04/imagen_2026-04-22_191513341.png\" data-object-fit=\"cover\"/><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim-0 has-background-dim\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:stackable/image {\"uniqueId\":\"03bd5f2\",\"imageUrl\":\"https://furbuddy.xyz/wp-content/uploads/2026/04/imagen_2026-04-22_191901510.png\",\"imageId\":1479,\"imageWidthAttribute\":263,\"imageHeightAttribute\":350,\"imageWidth\":263,\"imageWidthUnit\":\"px\"} -->\n<div class=\"wp-block-stackable-image stk-block-image stk-block stk-03bd5f2\" data-block-id=\"03bd5f2\"><style>.stk-03bd5f2 .stk-img-wrapper{width:263px !important;}</style><figure><span class=\"stk-img-wrapper stk-image--shape-stretch\"><img class=\"stk-img wp-image-1479\" src=\"https://furbuddy.xyz/wp-content/uploads/2026/04/imagen_2026-04-22_191901510.png\" width=\"263\" height=\"350\"/></span></figure></div>\n<!-- /wp:stackable/image -->\n\n<!-- wp:group {\"style\":{\"border\":{\"radius\":\"10px\"},\"spacing\":{\"padding\":{\"top\":\"30px\",\"bottom\":\"30px\",\"left\":\"30px\",\"right\":\"30px\"}}},\"backgroundColor\":\"white\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group has-white-background-color has-background\" style=\"border-radius:10px;padding-top:30px;padding-right:30px;padding-bottom:30px;padding-left:30px\"><!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group\"><!-- wp:group {\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:image {\"id\":1511,\"width\":\"40px\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"style\":{\"border\":{\"radius\":\"100px\"},\"spacing\":{\"margin\":{\"bottom\":\"10px\"}}}} -->\n<figure class=\"wp-block-image size-full is-resized has-custom-border\" style=\"margin-bottom:10px\"><img src=\"https://furbuddy.xyz/wp-content/uploads/2026/04/imagen_2026-04-22_193815824.png\" alt=\"\" class=\"wp-image-1511\" style=\"border-radius:100px;width:40px\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group -->\n\n<!-- wp:stackable/text {\"uniqueId\":\"44573ae\",\"blockMargin\":{\"bottom\":14},\"contentAlign\":\"left\"} -->\n<div class=\"wp-block-stackable-text stk-block-text stk-block stk-44573ae\" data-block-id=\"44573ae\"><style>.stk-44573ae {margin-bottom:14px !important;}</style><p class=\"stk-block-text__text has-text-align-left\"><strong>Laura Beatriz Navarro</strong></p></div>\n<!-- /wp:stackable/text --></div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"margin\":{\"bottom\":\"30px\"}},\"elements\":{\"link\":{\"color\":{\"text\":\"#000000a8\"}}},\"color\":{\"text\":\"#000000a8\"}}} -->\n<p class=\"has-text-color has-link-color\" style=\"color:#000000a8;margin-bottom:30px\">\"Creía que no encontraría ropa o accesorios para mi chihuahua, pero en la tienda hay incluso para razas pequeñas, le queda justo como quería\"</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div></div>\n<!-- /wp:cover --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:cover {\"url\":\"https://furbuddy.xyz/wp-content/uploads/2026/04/imagen_2026-04-22_191554979.png\",\"id\":1469,\"dimRatio\":0,\"isUserOverlayColor\":true,\"minHeight\":650,\"contentPosition\":\"bottom center\",\"isDark\":false,\"sizeSlug\":\"full\",\"style\":{\"border\":{\"radius\":\"20px\"},\"spacing\":{\"padding\":{\"top\":\"30px\",\"bottom\":\"30px\",\"left\":\"30px\",\"right\":\"30px\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-cover is-light has-custom-content-position is-position-bottom-center\" style=\"border-radius:20px;padding-top:30px;padding-right:30px;padding-bottom:30px;padding-left:30px;min-height:650px\"><img class=\"wp-block-cover__image-background wp-image-1469 size-full\" alt=\"\" src=\"https://furbuddy.xyz/wp-content/uploads/2026/04/imagen_2026-04-22_191554979.png\" data-object-fit=\"cover\"/><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim-0 has-background-dim\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:stackable/image {\"uniqueId\":\"33dc12a\",\"imageUrl\":\"https://furbuddy.xyz/wp-content/uploads/2026/04/imagen_2026-04-22_191932784.png\",\"imageId\":1482,\"imageWidthAttribute\":1024,\"imageHeightAttribute\":683} -->\n<div class=\"wp-block-stackable-image stk-block-image stk-block stk-33dc12a\" data-block-id=\"33dc12a\"><figure><span class=\"stk-img-wrapper stk-image--shape-stretch\"><img class=\"stk-img wp-image-1482\" src=\"https://furbuddy.xyz/wp-content/uploads/2026/04/imagen_2026-04-22_191932784.png\" width=\"1024\" height=\"683\"/></span></figure></div>\n<!-- /wp:stackable/image -->\n\n<!-- wp:group {\"style\":{\"border\":{\"radius\":\"10px\"},\"spacing\":{\"padding\":{\"top\":\"30px\",\"bottom\":\"30px\",\"left\":\"30px\",\"right\":\"30px\"}}},\"backgroundColor\":\"white\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group has-white-background-color has-background\" style=\"border-radius:10px;padding-top:30px;padding-right:30px;padding-bottom:30px;padding-left:30px\"><!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group\"><!-- wp:group {\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:image {\"id\":1511,\"width\":\"40px\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"style\":{\"border\":{\"radius\":\"100px\"},\"spacing\":{\"margin\":{\"bottom\":\"10px\"}}}} -->\n<figure class=\"wp-block-image size-full is-resized has-custom-border\" style=\"margin-bottom:10px\"><img src=\"https://furbuddy.xyz/wp-content/uploads/2026/04/imagen_2026-04-22_193815824.png\" alt=\"\" class=\"wp-image-1511\" style=\"border-radius:100px;width:40px\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group -->\n\n<!-- wp:stackable/text {\"uniqueId\":\"1fcd034\",\"blockMargin\":{\"bottom\":14},\"contentAlign\":\"left\"} -->\n<div class=\"wp-block-stackable-text stk-block-text stk-block stk-1fcd034\" data-block-id=\"1fcd034\"><style>.stk-1fcd034 {margin-bottom:14px !important;}</style><p class=\"stk-block-text__text has-text-align-left\"><strong>Gabriela Morales</strong></p></div>\n<!-- /wp:stackable/text --></div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"margin\":{\"bottom\":\"30px\"}},\"elements\":{\"link\":{\"color\":{\"text\":\"#000000a8\"}}},\"color\":{\"text\":\"#000000a8\"}}} -->\n<p class=\"has-text-color has-link-color\" style=\"color:#000000a8;margin-bottom:30px\">\"Los comederos y los productos así son bastante creativos, no se encuentran muchos productos así en las tiendas normales.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div></div>\n<!-- /wp:cover --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:stackable/divider {\"uniqueId\":\"071a98c\",\"blockMargin\":{\"bottom\":\"\"}} -->\n<div class=\"wp-block-stackable-divider stk-block-divider stk-block stk-071a98c\" data-block-id=\"071a98c\"><hr class=\"stk-block-divider__hr\"/></div>\n<!-- /wp:stackable/divider -->\n\n<!-- wp:stackable/call-to-action {\"uniqueId\":\"2461277\",\"blockMargin\":{\"bottom\":14},\"className\":\"is-style-default\"} -->\n<div class=\"wp-block-stackable-call-to-action stk-block-call-to-action stk-block stk-2461277 is-style-default\" data-v=\"2\" data-block-id=\"2461277\"><style>.stk-2461277 {margin-bottom:14px !important;}</style><div class=\"stk-block-call-to-action__content stk-content-align stk-2461277-column stk-container stk-2461277-container stk-hover-parent\"><div class=\"has-text-align-center stk-block-content stk-inner-blocks stk-2461277-inner-blocks\"><!-- wp:stackable/heading {\"uniqueId\":\"c8c8753\",\"blockMargin\":{\"bottom\":\"\"},\"textTag\":\"h3\"} -->\n<div class=\"wp-block-stackable-heading stk-block-heading stk-block-heading--v2 stk-block stk-c8c8753\" id=\"te-han-gustado-algunos-de-nuestros-productos-🐶-😺\" data-block-id=\"c8c8753\"><h3 class=\"stk-block-heading__text\">Te han gustado algunos de nuestros productos?🐶😺</h3></div>\n<!-- /wp:stackable/heading -->\n\n<!-- wp:stackable/text {\"uniqueId\":\"c1b63f8\",\"blockMargin\":{\"bottom\":0}} -->\n<div class=\"wp-block-stackable-text stk-block-text stk-block stk-c1b63f8\" data-block-id=\"c1b63f8\"><style>.stk-c1b63f8 {margin-bottom:0px !important;}</style><p class=\"stk-block-text__text\">Te invitamos a que busques en nuestra tienda el regalo perfecto para tu mascota </p></div>\n<!-- /wp:stackable/text -->\n\n<!-- wp:stackable/button-group {\"uniqueId\":\"cf71eb8\"} -->\n<div class=\"wp-block-stackable-button-group stk-block-button-group stk-block stk-cf71eb8\" data-block-id=\"cf71eb8\"><div class=\"stk-row stk-inner-blocks stk-block-content stk-button-group\"><!-- wp:stackable/button {\"uniqueId\":\"869fc28\"} -->\n<div class=\"wp-block-stackable-button stk-block-button stk-block stk-869fc28\" data-block-id=\"869fc28\"><a class=\"stk-link stk-button stk--hover-effect-darken\" href=\"\"><span class=\"stk-button__inner-text\">Tienda</span></a></div>\n<!-- /wp:stackable/button --></div></div>\n<!-- /wp:stackable/button-group -->\n\n<!-- wp:image {\"id\":1555,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"https://furbuddy.xyz/wp-content/uploads/2026/04/imagen_2026-04-22_201209878-1024x682.png\" alt=\"\" class=\"wp-image-1555\"/></figure>\n<!-- /wp:image --></div></div></div>\n<!-- /wp:stackable/call-to-action -->\n\n<!-- wp:stackable/columns {\"uniqueId\":\"ee17105\",\"blockBackgroundTintStrength\":5,\"blockMargin\":{\"top\":\"var(\\u002d\\u002dstk\\u002d\\u002dpreset\\u002d\\u002dspacing\\u002d\\u002d70, 3.38rem)\",\"right\":\"\",\"bottom\":\"var(\\u002d\\u002dstk\\u002d\\u002dpreset\\u002d\\u002dspacing\\u002d\\u002d70, 3.38rem)\",\"left\":\"\"},\"align\":\"full\",\"innerBlockContentAlign\":\"alignwide\"} -->\n<div class=\"wp-block-stackable-columns alignfull stk-block-columns stk-block stk-ee17105\" data-block-id=\"ee17105\"><style>.stk-ee17105 {margin-top:var(--stk--preset--spacing--70, 3.38rem) !important;margin-bottom:var(--stk--preset--spacing--70, 3.38rem) !important;}</style><div class=\"stk-row stk-inner-blocks stk-block-content stk-content-align stk-ee17105-column alignwide\"></div></div>\n<!-- /wp:stackable/columns -->','Testimonios','','