INSERT INTO `SERVMASK_PREFIX_posts` VALUES (1560,7,'2026-04-22 20:14:31','2026-04-23 02:14:31','<!-- wp:heading -->\n<h2 class=\"wp-block-heading\"><strong>“Cuidar de quienes siempre están para ti no es un gasto, es una responsabilidad. En cada producto hay bienestar, confianza y amor para tu mascota.”</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:stackable/divider {\"uniqueId\":\"f462cd7\",\"blockMargin\":{\"bottom\":\"\"}} -->\n<div class=\"wp-block-stackable-divider stk-block-divider stk-block stk-f462cd7\" data-block-id=\"f462cd7\"><hr class=\"stk-block-divider__hr\"/></div>\n<!-- /wp:stackable/divider -->\n\n<!-- wp:group {\"metadata\":{\"categories\":[\"blocksy\"],\"patternName\":\"blocksy/pattern-3\",\"name\":\"Blocksy - Text Cards\"},\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"7rem\",\"bottom\":\"7rem\"}}},\"backgroundColor\":\"white\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull has-white-background-color has-background\" style=\"padding-top:7rem;padding-bottom:7rem\"><!-- wp:group {\"metadata\":{\"categories\":[\"blocksy\"],\"patternName\":\"blocksy/pattern-4\",\"name\":\"Blocksy - Hero Section\"},\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"7rem\",\"bottom\":\"7rem\"}}},\"backgroundColor\":\"white\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull has-white-background-color has-background\" style=\"padding-top:7rem;padding-bottom:7rem\"><!-- wp:columns {\"verticalAlignment\":\"center\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|80\",\"left\":\"var:preset|spacing|80\"}}}} -->\n<div class=\"wp-block-columns are-vertically-aligned-center\"><!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"50%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:50%\"><!-- wp:heading {\"level\":1,\"style\":{\"typography\":{\"lineHeight\":\"1.2\",\"fontStyle\":\"normal\",\"fontWeight\":\"800\",\"f