INSERT INTO `SERVMASK_PREFIX_posts` VALUES (1648,1,'2026-05-12 10:36:19','2026-05-12 16:36:19','<!-- wp:stackable/columns {\"uniqueId\":\"763009c\",\"blockMargin\":{\"top\":\"var(\\u002d\\u002dstk\\u002d\\u002dpreset\\u002d\\u002dspacing\\u002d\\u002d70, 3.38rem)\",\"right\":\"\",\"bottom\":\"var(\\u002d\\u002dstk\\u002d\\u002dpreset\\u002d\\u002dspacing\\u002d\\u002d70, 3.38rem)\",\"left\":\"\"},\"align\":\"full\",\"innerBlockContentAlign\":\"alignwide\"} -->\n<div class=\"wp-block-stackable-columns alignfull stk-block-columns stk-block stk-763009c\" data-block-id=\"763009c\"><style>.stk-763009c {margin-top:var(--stk--preset--spacing--70, 3.38rem) !important;margin-bottom:var(--stk--preset--spacing--70, 3.38rem) !important;}</style><div class=\"stk-row stk-inner-blocks stk-block-content stk-content-align stk-763009c-column alignwide\"><!-- wp:stackable/column {\"uniqueId\":\"b39366a\",\"columnWidth\":49.4,\"columnAdjacentCount\":2,\"columnAlign\":\"center\"} -->\n<div class=\"wp-block-stackable-column stk-block-column stk-column stk-block stk-b39366a\" data-v=\"4\" data-block-id=\"b39366a\"><style>.stk-b39366a {align-self:center !important;}@media screen and (min-width: 768px){.stk-b39366a {flex:var(--stk-flex-grow, 1) 1 calc(49.4% - var(--stk-column-gap, 0px) * 1 / 2 ) !important;}}</style><div class=\"stk-column-wrapper stk-block-column__content stk-container stk-b39366a-container stk--no-background stk--no-padding\"><div class=\"stk-block-content stk-inner-blocks stk-b39366a-inner-blocks\"><!-- wp:stackable/heading {\"uniqueId\":\"92b3c4e\"} -->\n<div class=\"wp-block-stackable-heading stk-block-heading stk-block-heading--v2 stk-block stk-92b3c4e\" id=\"heading-placeholder\" data-block-id=\"92b3c4e\"><h2 class=\"stk-block-heading__text\">¡El Momento Favorito de su Día! 🐾</h2></div>\n<!-- /wp:stackable/heading -->\n\n<!-- wp:stackable/text {\"uniqueId\":\"f18949f\"} -->\n<div class=\"wp-block-stackable-text stk-block-text stk-block stk-f18949f\" data-block-id=\"f18949f\"><p class=\"stk-block-text__text\">Sorprendé a tu mascota con premios hechos en casa que les encantan. Recetas fáciles, saludables y deliciosas que harán que tu perro o gato no deje de pedir más. ¡Cociná felicidad!</p></div>\n<!-- /wp:stackable/text --></div></div></div>\n<!-- /wp:stackable/column -->\n\n<!-- wp:stackable/column {\"uniqueId\":\"2fe943f\",\"columnWidth\":50.599999999999994,\"columnAdjacentCount\":2} -->\n<div class=\"wp-block-stackable-column stk-block-column stk-column stk-block stk-2fe943f\" data-v=\"4\" data-block-id=\"2fe943f\"><style>@media screen and (min-width: 768px){.stk-2fe943f {flex:var(--stk-flex-grow, 1) 1 calc(50.599999999999994% - var(--stk-column-gap, 0px) * 1 / 2 ) !important;}}</style><div class=\"stk-column-wrapper stk-block-column__content stk-container stk-2fe943f-container stk--no-background stk--no-padding\"><div class=\"stk-block-content stk-inner-blocks stk-2fe943f-inner-blocks\"><!-- wp:stackable/image {\"uniqueId\":\"b681246\",\"imageUrl\":\"https://furbuddy.xyz/wp-content/uploads/2026/04/Gemini_Generated_Image_senbc1senbc1senb.webp\",\"imageId\":841,\"imageWidthAttribute\":614,\"imageHeightAttribute\":574} -->\n<div class=\"wp-block-stackable-image stk-block-image stk-block stk-b681246\" data-block-id=\"b681246\"><figure><span class=\"stk-img-wrapper stk-image--shape-stretch\"><img class=\"stk-img wp-image-841\" src=\"https://furbuddy.xyz/wp-content/uploads/2026/04/Gemini_Generated_Image_senbc1senbc1senb.webp\" width=\"614\" height=\"574\"/></span></figure></div>\n<!-- /wp:stackable/image --></div></div></div>\n<!-- /wp:stackable/column --></div></div>\n<!-- /wp:stackable/columns -->\n\n<!-- wp:stackable/columns {\"uniqueId\":\"4307100\",\"blockMargin\":{\"top\":\"var(\\u002d\\u002dstk\\u002d\\u002dpreset\\u002d\\u002dspacing\\u002d\\u002d70, 3.38rem)\",\"right\":\"\",\"bottom\":\"var(\\u002d\\u002dstk\\u002d\\u002dpreset\\u002d\\u002dspacing\\u002d\\u002d70, 3.38rem)\",\"left\":\"\"},\"align\":\"full\",\"innerBlockContentAlign\":\"alignwide\"} -->\n<div class=\"wp-block-stackable-columns alignfull stk-block-columns stk-block stk-4307100\" data-block-id=\"4307100\"><style>.stk-4307100 {margin-top:var(--stk--preset--spacing--70, 3.38rem) !important;margin-bottom:var(--stk--preset--spacing--70, 3.38rem) !important;}</style><div class=\"stk-row stk-inner-blocks stk-block-content stk-content-align stk-4307100-column alignwide\"><!-- wp:stackable/column {\"uniqueId\":\"eb766cc\"} -->\n<div class=\"wp-block-stackable-column stk-block-column stk-column stk-block stk-eb766cc\" data-v=\"4\" data-block-id=\"eb766cc\"><div class=\"stk-column-wrapper stk-block-column__content stk-container stk-eb766cc-container stk--no-background stk--no-padding\"><div class=\"stk-block-content stk-inner-blocks stk-eb766cc-inner-blocks\"><!-- wp:stackable/heading {\"contentAlign\":\"center\",\"uniqueId\":\"7eeaf3c\"} -->\n<div class=\"wp-block-stackable-heading stk-block-heading stk-block-heading--v2 stk-block stk-7eeaf3c\" id=\"heading-placeholder\" data-block-id=\"7eeaf3c\"><h2 class=\"stk-block-heading__text has-text-align-center\">Recetas caseras</h2></div>\n<!-- /wp:stackable/heading -->\n\n<!-- wp:stackable/columns {\"uniqueId\":\"e839a25\"} -->\n<div class=\"wp-block-stackable-columns stk-block-columns stk-block stk-e839a25\" data-block-id=\"e839a25\"><div class=\"stk-row stk-inner-blocks stk-block-content stk-content-align stk-e839a25-column\"><!-- wp:stackable/column {\"uniqueId\":\"a2fb2ab\"} -->\n<div class=\"wp-block-stackable-column stk-block-column stk-column stk-block stk-a2fb2ab\" data-v=\"4\" data-block-id=\"a2fb2ab\"><div class=\"stk-column-wrapper stk-block-column__content stk-container stk-a2fb2ab-container stk--no-background stk--no-padding\"><div class=\"stk-block-content stk-inner-blocks stk-a2fb2ab-inner-blocks\"><!-- wp:stackable/accordion {\"uniqueId\":\"55b5b23\",\"className\":\"is-style-default\"} -->\n<details class=\"wp-block-stackable-accordion stk-block-accordion stk-inner-blocks stk-block-content stk-block stk-55b5b23 is-style-default\" data-block-id=\"55b5b23\"><!-- wp:stackable/column {\"uniqueId\":\"c814b1b\",\"hasContainer\":true,\"htmlTag\":\"summary\",\"templateLock\":\"insert\",\"className\":\"stk\\u002d\\u002dcontainer-small stk-block-accordion__heading\"} -->\n<summary class=\"wp-block-stackable-column stk-block-column stk-column stk-block stk-c814b1b stk--container-small stk-block-accordion__heading\" data-v=\"4\" data-block-id=\"c814b1b\"><div class=\"stk-column-wrapper stk-block-column__content stk-container stk-c814b1b-container stk-hover-parent\"><div class=\"stk-block-content stk-inner-blocks stk-c814b1b-inner-blocks\"><!-- wp:stackable/icon-label {\"uniqueId\":\"d558cca\"} -->\n<div class=\"wp-block-stackable-icon-label stk-block-icon-label stk-block stk-d558cca\" data-block-id=\"d558cca\"><div class=\"stk-row stk-inner-blocks stk-block-content\"><!-- wp:stackable/heading {\"uniqueId\":\"02f39fb\",\"hasP\":true,\"textTag\":\"h3\"} -->\n<div class=\"wp-block-stackable-heading stk-block-heading stk-block-heading--v2 stk-block stk-02f39fb\" id=\"question-1-placeholder\" data-block-id=\"02f39fb\"><h3 class=\"stk-block-heading__text\">Galletas crujientes de avena y plátano</h3></div>\n<!-- /wp:stackable/heading -->\n\n<!-- wp:stackable/icon {\"uniqueId\":\"66d9075\",\"icon\":\"\\u003csvg data-prefix=\\u0022fas\\u0022 data-icon=\\u0022chevron-down\\u0022 class=\\u0022svg-inline\\u002d\\u002dfa fa-chevron-down fa-w-14\\u0022 xmlns=\\u0022http://www.w3.org/2000/svg\\u0022 viewBox=\\u00220 0 448 512\\u0022 aria-hidden=\\u0022true\\u0022\\u003e\\u003cpath fill=\\u0022currentColor\\u0022 d=\\u0022M207.029 381.476L12.686 187.132c-9.373-9.373-9.373-24.569 0-33.941l22.667-22.667c9.357-9.357 24.522-9.375 33.901-.04L224 284.505l154.745-154.021c9.379-9.335 24.544-9.317 33.901.04l22.667 22.667c9.373 9.373 9.373 24.569 0 33.941L240.971 381.476c-9.373 9.372-24.569 9.372-33.942 0z\\u0022\\u003e\\u003c/path\\u003e\\u003c/svg\\u003e\"} -->\n<div class=\"wp-block-stackable-icon stk-block-icon stk-block stk-66d9075\" data-block-id=\"66d9075\"><span class=\"stk--svg-wrapper\"><div class=\"stk--inner-svg\"><svg style=\"height:0;width:0\"><defs><linearGradient id=\"linear-gradient-66d9075\" x1=\"0\" x2=\"100%\" y1=\"0\" y2=\"0\"><stop offset=\"0%\" style=\"stop-opacity:1;stop-color:var(--linear-gradient-66-d-9075-color-1)\"></stop><stop offset=\"100%\" style=\"stop-opacity:1;stop-color:var(--linear-gradient-66-d-9075-color-2)\"></stop></linearGradient></defs></svg><svg data-prefix=\"fas\" data-icon=\"chevron-down\" class=\"svg-inline--fa fa-chevron-down fa-w-14\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 448 512\" aria-hidden=\"true\" width=\"32\" height=\"32\"><path fill=\"currentColor\" d=\"M207.029 381.476L12.686 187.132c-9.373-9.373-9.373-24.569 0-33.941l22.667-22.667c9.357-9.357 24.522-9.375 33.901-.04L224 284.505l154.745-154.021c9.379-9.335 24.544-9.317 33.901.04l22.667 22.667c9.373 9.373 9.373 24.569 0 33.941L240.971 381.476c-9.373 9.372-24.569 9.372-33.942 0z\"></path></svg></div></span></div>\n<!-- /wp:stackable/icon --></div></div>\n<!-- /wp:stackable/icon-label --></div></div></summary>\n<!-- /wp:stackable/column -->\n\n<!-- wp:stackable/column {\"uniqueId\":\"927ea78\",\"className\":\"stk-block-accordion__content\"} -->\n<div class=\"wp-block-stackable-column stk-block-column stk-column stk-block stk-927ea78 stk-block-accordion__content\" data-v=\"4\" data-block-id=\"927ea78\"><div class=\"stk-column-wrapper stk-block-column__content stk-container stk-927ea78-container stk--no-background stk--no-padding\"><div class=\"stk-block-content stk-inner-blocks stk-927ea78-inner-blocks\"><!-- wp:stackable/text {\"uniqueId\":\"18f40cb\"} -->\n<div class=\"wp-block-stackable-text stk-block-text stk-block stk-18f40cb\" data-block-id=\"18f40cb\"><p class=\"stk-block-text__text\">Para Perros</p></div>\n<!-- /wp:stackable/text -->\n\n<!-- wp:paragraph -->\n<p>Una opción excelente, económica y llena de fibra para consentir a los caninos de la casa. Además, es ideal para aprovechar esos plátanos maduros que se van quedando en la cocina.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Ingredientes:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>1 plátano maduro machacado.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>1 taza de avena en hojuelas (preferiblemente integral).</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>1/4 de taza de agua (o un chorrito si la masa queda muy seca).</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Procedimiento:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Coloca las porciones en una bandeja para hornear con papel vegetal y hornea durante 15 minutos o hasta que estén doradas y firmes. Dejar enfriar antes de servir.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Precalienta el horno a 180 °C.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>En un recipiente, machaca bien el plátano con un tenedor hasta hacerle puré.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Agrega la avena e integra todo. Si notas la mezcla demasiado compacta, añade un poco de agua hasta obtener una masa manejable.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Extiende la masa sobre una superficie limpia y córtala en pequeñas porciones (puedes usar moldes con formas divertidas como huesitos).</p>\n<!-- /wp:paragraph --></div></div></div>\n<!-- /wp:stackable/column --></details>\n<!-- /wp:stackable/accordion -->\n\n<!-- wp:stackable/accordion {\"uniqueId\":\"c75f651\",\"className\":\"is-style-default\"} -->\n<details class=\"wp-block-stackable-accordion stk-block-accordion stk-inner-blocks stk-block-content stk-block stk-c75f651 is-style-default\" data-block-id=\"c75f651\"><!-- wp:stackable/column {\"uniqueId\":\"f9813f2\",\"hasContainer\":true,\"htmlTag\":\"summary\",\"templateLock\":\"insert\",\"className\":\"stk\\u002d\\u002dcontainer-small stk-block-accordion__heading\"} -->\n<summary class=\"wp-block-stackable-column stk-block-column stk-column stk-block stk-f9813f2 stk--container-small stk-block-accordion__heading\" data-v=\"4\" data-block-id=\"f9813f2\"><div class=\"stk-column-wrapper stk-block-column__content stk-container stk-f9813f2-container stk-hover-parent\"><div class=\"stk-block-content stk-inner-blocks stk-f9813f2-inner-blocks\"><!-- wp:stackable/icon-label {\"uniqueId\":\"e1d2136\"} -->\n<div class=\"wp-block-stackable-icon-label stk-block-icon-label stk-block stk-e1d2136\" data-block-id=\"e1d2136\"><div class=\"stk-row stk-inner-blocks stk-block-content\"><!-- wp:stackable/heading {\"uniqueId\":\"f5489f3\",\"hasP\":true,\"textTag\":\"h3\"} -->\n<div class=\"wp-block-stackable-heading stk-block-heading stk-block-heading--v2 stk-block stk-f5489f3\" id=\"question-2-placeholder\" data-block-id=\"f5489f3\"><h3 class=\"stk-block-heading__text\">Caldo reconfortante de pollo y zanahoria</h3></div>\n<!-- /wp:stackable/heading -->\n\n<!-- wp:stackable/icon {\"uniqueId\":\"934bba4\",\"icon\":\"\\u003csvg data-prefix=\\u0022fas\\u0022 data-icon=\\u0022chevron-down\\u0022 class=\\u0022svg-inline\\u002d\\u002dfa fa-chevron-down fa-w-14\\u0022 xmlns=\\u0022http://www.w3.org/2000/svg\\u0022 viewBox=\\u00220 0 448 512\\u0022 aria-hidden=\\u0022true\\u0022\\u003e\\u003cpath fill=\\u0022currentColor\\u0022 d=\\u0022M207.029 381.476L12.686 187.132c-9.373-9.373-9.373-24.569 0-33.941l22.667-22.667c9.357-9.357 24.522-9.375 33.901-.04L224 284.505l154.745-154.021c9.379-9.335 24.544-9.317 33.901.04l22.667 22.667c9.373 9.373 9.373 24.569 0 33.941L240.971 381.476c-9.373 9.372-24.569 9.372-33.942 0z\\u0022\\u003e\\u003c/path\\u003e\\u003c/svg\\u003e\"} -->\n<div class=\"wp-block-stackable-icon stk-block-icon stk-block stk-934bba4\" data-block-id=\"934bba4\"><span class=\"stk--svg-wrapper\"><div class=\"stk--inner-svg\"><svg style=\"height:0;width:0\"><defs><linearGradient id=\"linear-gradient-934bba4\" x1=\"0\" x2=\"100%\" y1=\"0\" y2=\"0\"><stop offset=\"0%\" style=\"stop-opacity:1;stop-color:var(--linear-gradient-934-bba-4-color-1)\"></stop><stop offset=\"100%\" style=\"stop-opacity:1;stop-color:var(--linear-gradient-934-bba-4-color-2)\"></stop></linearGradient></defs></svg><svg data-prefix=\"fas\" data-icon=\"chevron-down\" class=\"svg-inline--fa fa-chevron-down fa-w-14\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 448 512\" aria-hidden=\"true\" width=\"32\" height=\"32\"><path fill=\"currentColor\" d=\"M207.029 381.476L12.686 187.132c-9.373-9.373-9.373-24.569 0-33.941l22.667-22.667c9.357-9.357 24.522-9.375 33.901-.04L224 284.505l154.745-154.021c9.379-9.335 24.544-9.317 33.901.04l22.667 22.667c9.373 9.373 9.373 24.569 0 33.941L240.971 381.476c-9.373 9.372-24.569 9.372-33.942 0z\"></path></svg></div></span></div>\n<!-- /wp:stackable/icon --></div></div>\n<!-- /wp:stackable/icon-label --></div></div></summary>\n<!-- /wp:stackable/column -->\n\n<!-- wp:stackable/column {\"uniqueId\":\"23760e0\",\"className\":\"stk-block-accordion__content\"} -->\n<div class=\"wp-block-stackable-column stk-block-column stk-column stk-block stk-23760e0 stk-block-accordion__content\" data-v=\"4\" data-block-id=\"23760e0\"><div class=\"stk-column-wrapper stk-block-column__content stk-container stk-23760e0-container stk--no-background stk--no-padding\"><div class=\"stk-block-content stk-inner-blocks stk-23760e0-inner-blocks\"><!-- wp:stackable/text {\"uniqueId\":\"6bfe261\"} -->\n<div class=\"wp-block-stackable-text stk-block-text stk-block stk-6bfe261\" data-block-id=\"6bfe261\"><p class=\"stk-block-text__text\">Para Gatos y Perros</p></div>\n<!-- /wp:stackable/text -->\n\n<!-- wp:paragraph -->\n<p>Este caldo es una herramienta fantástica para mantener hidratadas a las mascotas, especialmente a los gatos, quienes suelen beber poca agua. Se puede servir solo o sobre su comida seca.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Ingredientes:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>1 pechuga de pollo (sin piel y sin huesos).</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>1 zanahoria mediana picada en rodajas.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Agua suficiente para cubrir los ingredientes.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><em>Nota importante: No añadir sal, cebolla, ajo ni condimentos.</em></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Procedimiento:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Deja enfriar a temperatura ambiente antes de servirle una porción a tu mascota. El resto se puede congelar en cubitos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>En una olla pequeña, coloca la pechuga de pollo y las rodajas de zanahoria.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Cubre por completo con agua y ponlo a hervir a fuego medio-alto.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Una vez que hierva, baja el fuego y cocina tapado durante unos 20 o 25 minutos, hasta que el pollo esté bien cocido.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Retira el pollo y desmenúzalo (o procésalo junto al caldo si prefieres una textura tipo crema).</p>\n<!-- /wp:paragraph --></div></div></div>\n<!-- /wp:stackable/column --></details>\n<!-- /wp:stackable/accordion -->\n\n<!-- wp:stackable/accordion {\"uniqueId\":\"1b0d514\",\"className\":\"is-style-default\"} -->\n<details class=\"wp-block-stackable-accordion stk-block-accordion stk-inner-blocks stk-block-content stk-block stk-1b0d514 is-style-default\" data-block-id=\"1b0d514\"><!-- wp:stackable/column {\"uniqueId\":\"e5d889d\",\"hasContainer\":true,\"htmlTag\":\"summary\",\"templateLock\":\"insert\",\"className\":\"stk\\u002d\\u002dcontainer-small stk-block-accordion__heading\"} -->\n<summary class=\"wp-block-stackable-column stk-block-column stk-column stk-block stk-e5d889d stk--container-small stk-block-accordion__heading\" data-v=\"4\" data-block-id=\"e5d889d\"><div class=\"stk-column-wrapper stk-block-column__content stk-container stk-e5d889d-container stk-hover-parent\"><div class=\"stk-block-content stk-inner-blocks stk-e5d889d-inner-blocks\"><!-- wp:stackable/icon-label {\"uniqueId\":\"b9699e1\"} -->\n<div class=\"wp-block-stackable-icon-label stk-block-icon-label stk-block stk-b9699e1\" data-block-id=\"b9699e1\"><div class=\"stk-row stk-inner-blocks stk-block-content\"><!-- wp:stackable/heading {\"uniqueId\":\"ca68042\",\"hasP\":true,\"textTag\":\"h3\"} -->\n<div class=\"wp-block-stackable-heading stk-block-heading stk-block-heading--v2 stk-block stk-ca68042\" id=\"question-3-placeholder\" data-block-id=\"ca68042\"><h3 class=\"stk-block-heading__text\">Helado refrescante de yogur y fresa</h3></div>\n<!-- /wp:stackable/heading -->\n\n<!-- wp:stackable/icon {\"uniqueId\":\"81a4945\",\"icon\":\"\\u003csvg data-prefix=\\u0022fas\\u0022 data-icon=\\u0022chevron-down\\u0022 class=\\u0022svg-inline\\u002d\\u002dfa fa-chevron-down fa-w-14\\u0022 xmlns=\\u0022http://www.w3.org/2000/svg\\u0022 viewBox=\\u00220 0 448 512\\u0022 aria-hidden=\\u0022true\\u0022\\u003e\\u003cpath fill=\\u0022currentColor\\u0022 d=\\u0022M207.029 381.476L12.686 187.132c-9.373-9.373-9.373-24.569 0-33.941l22.667-22.667c9.357-9.357 24.522-9.375 33.901-.04L224 284.505l154.745-154.021c9.379-9.335 24.544-9.317 33.901.04l22.667 22.667c9.373 9.373 9.373 24.569 0 33.941L240.971 381.476c-9.373 9.372-24.569 9.372-33.942 0z\\u0022\\u003e\\u003c/path\\u003e\\u003c/svg\\u003e\"} -->\n<div class=\"wp-block-stackable-icon stk-block-icon stk-block stk-81a4945\" data-block-id=\"81a4945\"><span class=\"stk--svg-wrapper\"><div class=\"stk--inner-svg\"><svg style=\"height:0;width:0\"><defs><linearGradient id=\"linear-gradient-81a4945\" x1=\"0\" x2=\"100%\" y1=\"0\" y2=\"0\"><stop offset=\"0%\" style=\"stop-opacity:1;stop-color:var(--linear-gradient-81-a-4945-color-1)\"></stop><stop offset=\"100%\" style=\"stop-opacity:1;stop-color:var(--linear-gradient-81-a-4945-color-2)\"></stop></linearGradient></defs></svg><svg data-prefix=\"fas\" data-icon=\"chevron-down\" class=\"svg-inline--fa fa-chevron-down fa-w-14\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 448 512\" aria-hidden=\"true\" width=\"32\" height=\"32\"><path fill=\"currentColor\" d=\"M207.029 381.476L12.686 187.132c-9.373-9.373-9.373-24.569 0-33.941l22.667-22.667c9.357-9.357 24.522-9.375 33.901-.04L224 284.505l154.745-154.021c9.379-9.335 24.544-9.317 33.901.04l22.667 22.667c9.373 9.373 9.373 24.569 0 33.941L240.971 381.476c-9.373 9.372-24.569 9.372-33.942 0z\"></path></svg></div></span></div>\n<!-- /wp:stackable/icon --></div></div>\n<!-- /wp:stackable/icon-label --></div></div></summary>\n<!-- /wp:stackable/column -->\n\n<!-- wp:stackable/column {\"uniqueId\":\"d70cda4\",\"className\":\"stk-block-accordion__content\"} -->\n<div class=\"wp-block-stackable-column stk-block-column stk-column stk-block stk-d70cda4 stk-block-accordion__content\" data-v=\"4\" data-block-id=\"d70cda4\"><div class=\"stk-column-wrapper stk-block-column__content stk-container stk-d70cda4-container stk--no-background stk--no-padding\"><div class=\"stk-block-content stk-inner-blocks stk-d70cda4-inner-blocks\"><!-- wp:stackable/text {\"uniqueId\":\"95be902\"} -->\n<div class=\"wp-block-stackable-text stk-block-text stk-block stk-95be902\" data-block-id=\"95be902\"><p class=\"stk-block-text__text\">Para Perros</p></div>\n<!-- /wp:stackable/text -->\n\n<!-- wp:paragraph -->\n<p>El premio perfecto para los días calurosos. Este \"helado\" casero aporta calcio, probióticos y vitaminas sin azúcares añadidos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Ingredientes:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>1 taza de yogur griego natural (100% sin azúcar y sin xilitol).</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>4 o 5 fresas frescas y bien lavadas.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>1 chorrito de agua o caldo de pollo (sin sal ni cebolla) si se prefiere una textura más ligera.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Procedimiento:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Desmolda y sirve uno a la vez para mantenerlos frescos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Quita las hojas verdes a las fresas y pícalas en trozos pequeños.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>En una licuadora o procesador, mezcla el yogur con las fresas hasta obtener un puré homogéneo.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Vierte la mezcla en moldes de silicona para hielo o moldes con formas divertidas.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Introduce en el congelador durante al menos 4 horas o hasta que estén completamente sólidos.</p>\n<!-- /wp:paragraph --></div></div></div>\n<!-- /wp:stackable/column --></details>\n<!-- /wp:stackable/accordion --></div></div></div>\n<!-- /wp:stackable/column -->\n\n<!-- wp:stackable/column {\"uniqueId\":\"4354a94\"} -->\n<div class=\"wp-block-stackable-column stk-block-column stk-column stk-block stk-4354a94\" data-v=\"4\" data-block-id=\"4354a94\"><div class=\"stk-column-wrapper stk-block-column__content stk-container stk-4354a94-container stk--no-background stk--no-padding\"><div class=\"stk-block-content stk-inner-blocks stk-4354a94-inner-blocks\"><!-- wp:stackable/accordion {\"uniqueId\":\"0d39b23\",\"className\":\"is-style-default\"} -->\n<details class=\"wp-block-stackable-accordion stk-block-accordion stk-inner-blocks stk-block-content stk-block stk-0d39b23 is-style-default\" data-block-id=\"0d39b23\"><!-- wp:stackable/column {\"uniqueId\":\"6b01f14\",\"hasContainer\":true,\"htmlTag\":\"summary\",\"templateLock\":\"insert\",\"className\":\"stk\\u002d\\u002dcontainer-small stk-block-accordion__heading\"} -->\n<summary class=\"wp-block-stackable-column stk-block-column stk-column stk-block stk-6b01f14 stk--container-small stk-block-accordion__heading\" data-v=\"4\" data-block-id=\"6b01f14\"><div class=\"stk-column-wrapper stk-block-column__content stk-container stk-6b01f14-container stk-hover-parent\"><div class=\"stk-block-content stk-inner-blocks stk-6b01f14-inner-blocks\"><!-- wp:stackable/icon-label {\"uniqueId\":\"672c43c\"} -->\n<div class=\"wp-block-stackable-icon-label stk-block-icon-label stk-block stk-672c43c\" data-block-id=\"672c43c\"><div class=\"stk-row stk-inner-blocks stk-block-content\"><!-- wp:stackable/heading {\"uniqueId\":\"8127d66\",\"hasP\":true,\"textTag\":\"h3\"} -->\n<div class=\"wp-block-stackable-heading stk-block-heading stk-block-heading--v2 stk-block stk-8127d66\" id=\"question-4-placeholder\" data-block-id=\"8127d66\"><h3 class=\"stk-block-heading__text\">Bocaditos horneados de atún</h3></div>\n<!-- /wp:stackable/heading -->\n\n<!-- wp:stackable/icon {\"uniqueId\":\"5fe35c4\",\"icon\":\"\\u003csvg data-prefix=\\u0022fas\\u0022 data-icon=\\u0022chevron-down\\u0022 class=\\u0022svg-inline\\u002d\\u002dfa fa-chevron-down fa-w-14\\u0022 xmlns=\\u0022http://www.w3.org/2000/svg\\u0022 viewBox=\\u00220 0 448 512\\u0022 aria-hidden=\\u0022true\\u0022\\u003e\\u003cpath fill=\\u0022currentColor\\u0022 d=\\u0022M207.029 381.476L12.686 187.132c-9.373-9.373-9.373-24.569 0-33.941l22.667-22.667c9.357-9.357 24.522-9.375 33.901-.04L224 284.505l154.745-154.021c9.379-9.335 24.544-9.317 33.901.04l22.667 22.667c9.373 9.373 9.373 24.569 0 33.941L240.971 381.476c-9.373 9.372-24.569 9.372-33.942 0z\\u0022\\u003e\\u003c/path\\u003e\\u003c/svg\\u003e\"} -->\n<div class=\"wp-block-stackable-icon stk-block-icon stk-block stk-5fe35c4\" data-block-id=\"5fe35c4\"><span class=\"stk--svg-wrapper\"><div class=\"stk--inner-svg\"><svg style=\"height:0;width:0\"><defs><linearGradient id=\"linear-gradient-5fe35c4\" x1=\"0\" x2=\"100%\" y1=\"0\" y2=\"0\"><stop offset=\"0%\" style=\"stop-opacity:1;stop-color:var(--linear-gradient-5-fe-35-c-4-color-1)\"></stop><stop offset=\"100%\" style=\"stop-opacity:1;stop-color:var(--linear-gradient-5-fe-35-c-4-color-2)\"></stop></linearGradient></defs></svg><svg data-prefix=\"fas\" data-icon=\"chevron-down\" class=\"svg-inline--fa fa-chevron-down fa-w-14\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 448 512\" aria-hidden=\"true\" width=\"32\" height=\"32\"><path fill=\"currentColor\" d=\"M207.029 381.476L12.686 187.132c-9.373-9.373-9.373-24.569 0-33.941l22.667-22.667c9.357-9.357 24.522-9.375 33.901-.04L224 284.505l154.745-154.021c9.379-9.335 24.544-9.317 33.901.04l22.667 22.667c9.373 9.373 9.373 24.569 0 33.941L240.971 381.476c-9.373 9.372-24.569 9.372-33.942 0z\"></path></svg></div></span></div>\n<!-- /wp:stackable/icon --></div></div>\n<!-- /wp:stackable/icon-label --></div></div></summary>\n<!-- /wp:stackable/column -->\n\n<!-- wp:stackable/column {\"uniqueId\":\"e2260e5\",\"className\":\"stk-block-accordion__content\"} -->\n<div class=\"wp-block-stackable-column stk-block-column stk-column stk-block stk-e2260e5 stk-block-accordion__content\" data-v=\"4\" data-block-id=\"e2260e5\"><div class=\"stk-column-wrapper stk-block-column__content stk-container stk-e2260e5-container stk--no-background stk--no-padding\"><div class=\"stk-block-content stk-inner-blocks stk-e2260e5-inner-blocks\"><!-- wp:stackable/text {\"uniqueId\":\"d5c1b72\"} -->\n<div class=\"wp-block-stackable-text stk-block-text stk-block stk-d5c1b72\" data-block-id=\"d5c1b72\"><p class=\"stk-block-text__text\">Para Gatos</p></div>\n<!-- /wp:stackable/text -->\n\n<!-- wp:paragraph -->\n<p>A los felinos les fascina el aroma del pescado, y estos bocaditos se convertirán en su premio favorito. Son crujientes por fuera y suaves por dentro.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Ingredientes:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>1 lata de atún al natural (bajo en sal y escurrido).</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>1 huevo.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>1/2 taza de harina de avena o harina de trigo integral.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Procedimiento:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Colócalas en una bandeja y hornea por unos 10 o 12 minutos. Déjalas enfriar por completo y guárdalas en un frasco hermético en la nevera.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Precalienta el horno a 180 °C.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Desmenuza muy bien el atún escurrido en un bol y mezcla con el huevo batido.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Añade la harina poco a poco mientras mezclas hasta formar una masa suave que no se pegue en las manos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Forma pequeñas bolitas del tamaño de una canica (adecuadas para la boca de un gato) y aplánalas ligeramente.</p>\n<!-- /wp:paragraph --></div></div></div>\n<!-- /wp:stackable/column --></details>\n<!-- /wp:stackable/accordion -->\n\n<!-- wp:stackable/accordion {\"uniqueId\":\"58ce2bb\",\"className\":\"is-style-default\"} -->\n<details class=\"wp-block-stackable-accordion stk-block-accordion stk-inner-blocks stk-block-content stk-block stk-58ce2bb is-style-default\" data-block-id=\"58ce2bb\"><!-- wp:stackable/column {\"uniqueId\":\"d454081\",\"hasContainer\":true,\"htmlTag\":\"summary\",\"templateLock\":\"insert\",\"className\":\"stk\\u002d\\u002dcontainer-small stk-block-accordion__heading\"} -->\n<summary class=\"wp-block-stackable-column stk-block-column stk-column stk-block stk-d454081 stk--container-small stk-block-accordion__heading\" data-v=\"4\" data-block-id=\"d454081\"><div class=\"stk-column-wrapper stk-block-column__content stk-container stk-d454081-container stk-hover-parent\"><div class=\"stk-block-content stk-inner-blocks stk-d454081-inner-blocks\"><!-- wp:stackable/icon-label {\"uniqueId\":\"688a1cc\"} -->\n<div class=\"wp-block-stackable-icon-label stk-block-icon-label stk-block stk-688a1cc\" data-block-id=\"688a1cc\"><div class=\"stk-row stk-inner-blocks stk-block-content\"><!-- wp:stackable/heading {\"uniqueId\":\"309e17a\",\"hasP\":true,\"textTag\":\"h3\"} -->\n<div class=\"wp-block-stackable-heading stk-block-heading stk-block-heading--v2 stk-block stk-309e17a\" id=\"question-5-placeholder\" data-block-id=\"309e17a\"><h3 class=\"stk-block-heading__text\">Bites crujientes de heno y manzana</h3></div>\n<!-- /wp:stackable/heading -->\n\n<!-- wp:stackable/icon {\"uniqueId\":\"25aad39\",\"icon\":\"\\u003csvg data-prefix=\\u0022fas\\u0022 data-icon=\\u0022chevron-down\\u0022 class=\\u0022svg-inline\\u002d\\u002dfa fa-chevron-down fa-w-14\\u0022 xmlns=\\u0022http://www.w3.org/2000/svg\\u0022 viewBox=\\u00220 0 448 512\\u0022 aria-hidden=\\u0022true\\u0022\\u003e\\u003cpath fill=\\u0022currentColor\\u0022 d=\\u0022M207.029 381.476L12.686 187.132c-9.373-9.373-9.373-24.569 0-33.941l22.667-22.667c9.357-9.357 24.522-9.375 33.901-.04L224 284.505l154.745-154.021c9.379-9.335 24.544-9.317 33.901.04l22.667 22.667c9.373 9.373 9.373 24.569 0 33.941L240.971 381.476c-9.373 9.372-24.569 9.372-33.942 0z\\u0022\\u003e\\u003c/path\\u003e\\u003c/svg\\u003e\"} -->\n<div class=\"wp-block-stackable-icon stk-block-icon stk-block stk-25aad39\" data-block-id=\"25aad39\"><span class=\"stk--svg-wrapper\"><div class=\"stk--inner-svg\"><svg style=\"height:0;width:0\"><defs><linearGradient id=\"linear-gradient-25aad39\" x1=\"0\" x2=\"100%\" y1=\"0\" y2=\"0\"><stop offset=\"0%\" style=\"stop-opacity:1;stop-color:var(--linear-gradient-25-aad-39-color-1)\"></stop><stop offset=\"100%\" style=\"stop-opacity:1;stop-color:var(--linear-gradient-25-aad-39-color-2)\"></stop></linearGradient></defs></svg><svg data-prefix=\"fas\" data-icon=\"chevron-down\" class=\"svg-inline--fa fa-chevron-down fa-w-14\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 448 512\" aria-hidden=\"true\" width=\"32\" height=\"32\"><path fill=\"currentColor\" d=\"M207.029 381.476L12.686 187.132c-9.373-9.373-9.373-24.569 0-33.941l22.667-22.667c9.357-9.357 24.522-9.375 33.901-.04L224 284.505l154.745-154.021c9.379-9.335 24.544-9.317 33.901.04l22.667 22.667c9.373 9.373 9.373 24.569 0 33.941L240.971 381.476c-9.373 9.372-24.569 9.372-33.942 0z\"></path></svg></div></span></div>\n<!-- /wp:stackable/icon --></div></div>\n<!-- /wp:stackable/icon-label --></div></div></summary>\n<!-- /wp:stackable/column -->\n\n<!-- wp:stackable/column {\"uniqueId\":\"1ca17fd\",\"className\":\"stk-block-accordion__content\"} -->\n<div class=\"wp-block-stackable-column stk-block-column stk-column stk-block stk-1ca17fd stk-block-accordion__content\" data-v=\"4\" data-block-id=\"1ca17fd\"><div class=\"stk-column-wrapper stk-block-column__content stk-container stk-1ca17fd-container stk--no-background stk--no-padding\"><div class=\"stk-block-content stk-inner-blocks stk-1ca17fd-inner-blocks\"><!-- wp:stackable/text {\"uniqueId\":\"d97f1cc\"} -->\n<div class=\"wp-block-stackable-text stk-block-text stk-block stk-d97f1cc\" data-block-id=\"d97f1cc\"><p class=\"stk-block-text__text\">Para Conejos y Cobayas</p></div>\n<!-- /wp:stackable/text -->\n\n<!-- wp:paragraph -->\n<p>Los pequeños herbívoros también merecen un premio especial. Esta receta utiliza sus ingredientes base favoritos para crear un snack divertido y crujiente que ayuda al desgaste de sus dientes.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Ingredientes:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>1/2 taza de manzana verde rallada (sin semillas ni corazón).</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>1 taza de heno picado finamente (el que consuman habitualmente).</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>2 o 3 cucharadas de agua tibia.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Procedimiento:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Colócalas en una bandeja y hornéalas durante 30 minutos a fuego bajo para que se deshidraten y queden bien crujientes. Deja enfriar por completo antes de ofrecérselas.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Precalienta el horno a 150 °C (fuego bajo).</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>En un bol, mezcla la manzana rallada con el heno bien troceado.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Agrega las cucharadas de agua tibia poco a poco y presiona la mezcla con las manos para que la textura de la manzana ayude a compactar el heno.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Forma pequeñas pastillas planas o galletitas compactas apretando fuerte con los dedos para que no se desarmen.</p>\n<!-- /wp:paragraph --></div></div></div>\n<!-- /wp:stackable/column --></details>\n<!-- /wp:stackable/accordion -->\n\n<!-- wp:stackable/accordion {\"uniqueId\":\"c069505\",\"className\":\"is-style-default\"} -->\n<details class=\"wp-block-stackable-accordion stk-block-accordion stk-inner-blocks stk-block-content stk-block stk-c069505 is-style-default\" data-block-id=\"c069505\"><!-- wp:stackable/column {\"uniqueId\":\"69cddfd\",\"hasContainer\":true,\"htmlTag\":\"summary\",\"templateLock\":\"insert\",\"className\":\"stk\\u002d\\u002dcontainer-small stk-block-accordion__heading\"} -->\n<summary class=\"wp-block-stackable-column stk-block-column stk-column stk-block stk-69cddfd stk--container-small stk-block-accordion__heading\" data-v=\"4\" data-block-id=\"69cddfd\"><div class=\"stk-column-wrapper stk-block-column__content stk-container stk-69cddfd-container stk-hover-parent\"><div class=\"stk-block-content stk-inner-blocks stk-69cddfd-inner-blocks\"><!-- wp:stackable/icon-label {\"uniqueId\":\"99219d2\"} -->\n<div class=\"wp-block-stackable-icon-label stk-block-icon-label stk-block stk-99219d2\" data-block-id=\"99219d2\"><div class=\"stk-row stk-inner-blocks stk-block-content\"><!-- wp:stackable/heading {\"uniqueId\":\"a62f1f9\",\"hasP\":true,\"textTag\":\"h3\"} -->\n<div class=\"wp-block-stackable-heading stk-block-heading stk-block-heading--v2 stk-block stk-a62f1f9\" id=\"question-6-placeholder\" data-block-id=\"a62f1f9\"><h3 class=\"stk-block-heading__text\">Albóndigas de pollo y camote</h3></div>\n<!-- /wp:stackable/heading -->\n\n<!-- wp:stackable/icon {\"uniqueId\":\"d498e44\",\"icon\":\"\\u003csvg data-prefix=\\u0022fas\\u0022 data-icon=\\u0022chevron-down\\u0022 class=\\u0022svg-inline\\u002d\\u002dfa fa-chevron-down fa-w-14\\u0022 xmlns=\\u0022http://www.w3.org/2000/svg\\u0022 viewBox=\\u00220 0 448 512\\u0022 aria-hidden=\\u0022true\\u0022\\u003e\\u003cpath fill=\\u0022currentColor\\u0022 d=\\u0022M207.029 381.476L12.686 187.132c-9.373-9.373-9.373-24.569 0-33.941l22.667-22.667c9.357-9.357 24.522-9.375 33.901-.04L224 284.505l154.745-154.021c9.379-9.335 24.544-9.317 33.901.04l22.667 22.667c9.373 9.373 9.373 24.569 0 33.941L240.971 381.476c-9.373 9.372-24.569 9.372-33.942 0z\\u0022\\u003e\\u003c/path\\u003e\\u003c/svg\\u003e\"} -->\n<div class=\"wp-block-stackable-icon stk-block-icon stk-block stk-d498e44\" data-block-id=\"d498e44\"><span class=\"stk--svg-wrapper\"><div class=\"stk--inner-svg\"><svg style=\"height:0;width:0\"><defs><linearGradient id=\"linear-gradient-d498e44\" x1=\"0\" x2=\"100%\" y1=\"0\" y2=\"0\"><stop offset=\"0%\" style=\"stop-opacity:1;stop-color:var(--linear-gradient-d-498-e-44-color-1)\"></stop><stop offset=\"100%\" style=\"stop-opacity:1;stop-color:var(--linear-gradient-d-498-e-44-color-2)\"></stop></linearGradient></defs></svg><svg data-prefix=\"fas\" data-icon=\"chevron-down\" class=\"svg-inline--fa fa-chevron-down fa-w-14\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 448 512\" aria-hidden=\"true\" width=\"32\" height=\"32\"><path fill=\"currentColor\" d=\"M207.029 381.476L12.686 187.132c-9.373-9.373-9.373-24.569 0-33.941l22.667-22.667c9.357-9.357 24.522-9.375 33.901-.04L224 284.505l154.745-154.021c9.379-9.335 24.544-9.317 33.901.04l22.667 22.667c9.373 9.373 9.373 24.569 0 33.941L240.971 381.476c-9.373 9.372-24.569 9.372-33.942 0z\"></path></svg></div></span></div>\n<!-- /wp:stackable/icon --></div></div>\n<!-- /wp:stackable/icon-label --></div></div></summary>\n<!-- /wp:stackable/column -->\n\n<!-- wp:stackable/column {\"uniqueId\":\"ff94221\",\"className\":\"stk-block-accordion__content\"} -->\n<div class=\"wp-block-stackable-column stk-block-column stk-column stk-block stk-ff94221 stk-block-accordion__content\" data-v=\"4\" data-block-id=\"ff94221\"><div class=\"stk-column-wrapper stk-block-column__content stk-container stk-ff94221-container stk--no-background stk--no-padding\"><div class=\"stk-block-content stk-inner-blocks stk-ff94221-inner-blocks\"><!-- wp:stackable/text {\"uniqueId\":\"73e4884\"} -->\n<div class=\"wp-block-stackable-text stk-block-text stk-block stk-73e4884\" data-block-id=\"73e4884\"><p class=\"stk-block-text__text\">Para Perros</p></div>\n<!-- /wp:stackable/text -->\n\n<!-- wp:paragraph -->\n<p>Una receta llena de proteína de alta calidad y carbohidratos de fácil digestión. Ideales como un extra en su plato o para rellenar juguetes interactivos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Ingredientes:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>200 gramos de carne molida de pollo o pavo.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>1/2 taza de puré de camote cocido (hervido solo con agua, sin sal).</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>2 cucharadas de harina de avena para dar consistencia.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Procedimiento:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Colócalas en una fuente para horno y cocínalas durante 15 a 20 minutos, asegurándote de que el pollo esté bien cocinado en el centro. Deja enfriar antes de consentir a tu peludo.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Precalienta el horno a 180 °C.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>En un recipiente espacioso, mezcla la carne molida de pollo con el puré de camote hasta que queden perfectamente integrados.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Añade la harina de avena y amasa un poco para compactar la mezcla.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Toma pequeñas porciones con las manos y dales forma de albóndigas del tamaño adecuado para tu perro.</p>\n<!-- /wp:paragraph --></div></div></div>\n<!-- /wp:stackable/column --></details>\n<!-- /wp:stackable/accordion --></div></div></div>\n<!-- /wp:stackable/column --></div></div>\n<!-- /wp:stackable/columns --></div></div></div>\n<!-- /wp:stackable/column --></div></div>\n<!-- /wp:stackable/columns -->\n\n<!-- wp:stackable/columns {\"uniqueId\":\"10bc3dc\",\"blockVerticalAlign\":\"center\",\"blockMargin\":{\"top\":\"var(\\u002d\\u002dstk\\u002d\\u002dpreset\\u002d\\u002dspacing\\u002d\\u002d70, 3.38rem)\",\"right\":\"\",\"bottom\":\"var(\\u002d\\u002dstk\\u002d\\u002dpreset\\u002d\\u002dspacing\\u002d\\u002d70, 3.38rem)\",\"left\":\"\"},\"blockHeight\":\"250\",\"align\":\"full\",\"innerBlockContentAlign\":\"alignwide\"} -->\n<div class=\"wp-block-stackable-columns alignfull stk-block-columns stk-block stk-10bc3dc\" data-block-id=\"10bc3dc\"><style>.stk-10bc3dc {min-height:250px !important;align-items:center !important;margin-top:var(--stk--preset--spacing--70, 3.38rem) !important;margin-bottom:var(--stk--preset--spacing--70, 3.38rem) !important;display:flex !important;}</style><div class=\"stk-row stk-inner-blocks stk-block-content stk-content-align stk-10bc3dc-column alignwide\"><!-- wp:stackable/column {\"uniqueId\":\"ec344c9\"} -->\n<div class=\"wp-block-stackable-column stk-block-column stk-column stk-block stk-ec344c9\" data-v=\"4\" data-block-id=\"ec344c9\"><div class=\"stk-column-wrapper stk-block-column__content stk-container stk-ec344c9-container stk--no-background stk--no-padding\"><div class=\"stk-block-content stk-inner-blocks stk-ec344c9-inner-blocks\"><!-- wp:stackable/subtitle {\"uniqueId\":\"4695b0e\",\"blockMargin\":{\"bottom\":\"\"},\"contentAlign\":\"center\",\"textTransform\":\"uppercase\"} -->\n<div class=\"wp-block-stackable-subtitle stk-block-subtitle stk-block stk-4695b0e\" data-block-id=\"4695b0e\"><style>.stk-4695b0e .stk-block-subtitle__text{text-transform:uppercase !important;}</style><p class=\"stk-block-subtitle__text stk-subtitle has-text-align-center\">Puedes encontrar mÁs de NUESTROS productos aquÍ </p></div>\n<!-- /wp:stackable/subtitle -->\n\n<!-- wp:stackable/heading {\"contentAlign\":\"center\",\"uniqueId\":\"7630126\",\"blockMargin\":{\"bottom\":\"\"}} -->\n<div class=\"wp-block-stackable-heading stk-block-heading stk-block-heading--v2 stk-block stk-7630126\" id=\"heading-placeholder\" data-block-id=\"7630126\"><h2 class=\"stk-block-heading__text has-text-align-center\">Explora nuestro gran catalogo para tu mascota</h2></div>\n<!-- /wp:stackable/heading -->\n\n<!-- wp:stackable/button-group {\"uniqueId\":\"6ede4c7\",\"contentAlign\":\"center\"} -->\n<div class=\"wp-block-stackable-button-group stk-block-button-group stk-block stk-6ede4c7\" data-block-id=\"6ede4c7\"><div class=\"stk-row stk-inner-blocks has-text-align-center stk-block-content stk-button-group\"><!-- wp:stackable/button {\"uniqueId\":\"6ad4f6a\"} -->\n<div class=\"wp-block-stackable-button stk-block-button stk-block stk-6ad4f6a\" data-block-id=\"6ad4f6a\"><a class=\"stk-link stk-button stk--hover-effect-darken\" href=\"https://furbuddy.xyz/tienda/\"><span class=\"stk-button__inner-text\">Visita nuestra tienda</span></a></div>\n<!-- /wp:stackable/button --></div></div>\n<!-- /wp:stackable/button-group --></div></div></div>\n<!-- /wp:stackable/column --></div></div>\n<!-- /wp:stackable/columns -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->','Recetas caseras','','inherit','closed','closed','','649-revision-v1','','','2026-05-12 10:36:19','2026-05-12 16:36:19','',649,'https://furbuddy.xyz/?p=1648',0,'revision','',0);
