INSERT INTO `SERVMASK_PREFIX_sib_model_forms` VALUES (1,'Default Form','<p class=\"sib-email-area\">\n    Email Address*\n    <input type=\"email\" class=\"sib-email-area\" name=\"email\" required=\"required\">\n</p>\n<p class=\"sib-FIRSTNAME-area\">\n    FIRSTNAME\n    <input type=\"text\" class=\"sib-FIRSTNAME-area\" name=\"FIRSTNAME\">\n</p>\n<p class=\"sib-LASTNAME-area\">\n    LASTNAME\n    <input type=\"text\" class=\"sib-LASTNAME-area\" name=\"LASTNAME\">\n</p>\n<p>\n    <input type=\"submit\" class=\"sib-default-btn\" value=\"Subscribe\">\n</p>\n','[form] {\n    padding: 5px;\n    -moz-box-sizing:border-box;\n    -webkit-box-sizing: border-box;\n    box-sizing: border-box;\n}\n[form] input[type=text],[form] input[type=email], [form] select {\n    width: 100%;\n    border: 1px solid #bbb;\n    height: auto;\n    margin: 5px 0 0 0;\n}\n[form] .sib-default-btn {\n    margin: 5px 0;\n    padding: 6px 12px;\n    color:#fff;\n    background-color: #333;\n    border-color: #2E2E2E;\n    font-size: 14px;\n    font-weight:400;\n    line-height: 1.4285;\n    text-align: center;\n    cursor: pointer;\n    vertical-align: middle;\n    -webkit-user-select:none;\n    -moz-user-select:none;\n    -ms-user-select:none;\n    user-select:none;\n    white-space: normal;\n    border:1px solid transparent;\n    border-radius: 3px;\n}\n[form] .sib-default-btn:hover {\n    background-color: #444;\n}\n[form] p{\n    margin: 10px 0 0 0;\n}\n',1,'a:1:{i:0;s:1:\"2\";}',-1,-1,0,0,NULL,NULL,'Thank you, you have successfully registered !','Something wrong occured','You have already registered','Your email address is invalid','Please fill out this field','email,NAME','2026-04-07',1,0,NULL,NULL,0,0,NULL,NULL,NULL,0,NULL);
