INSERT INTO `SERVMASK_PREFIX_wc_admin_notes` VALUES (35,'woopay-beta-merchantrecruitment-short-update-09MAY23','info','en_US','Increase conversions with WooPay — our fastest checkout yet','Be one of the first to try WooPay, our new express checkout feature. <br>Boost conversions by letting customers pay with a single click. <br><br>Update to the latest version of WooCommerce Payments to get started.','{}','pending','woocommerce.com','2026-02-18 23:39:05',NULL,0,'plain','',0,0,'info');
INSERT INTO `SERVMASK_PREFIX_wc_admin_notes` VALUES (36,'woocommerce-WCSubscriptions-June-2023-updated-needed','marketing','en_US','Action required: Security update of WooCommerce Subscriptions','<strong>Your store requires a security update for the WooCommerce Subscriptions plugin</strong>. Please update the WooCommerce Subscriptions plugin immediately to address a potential vulnerability.','{}','pending','woocommerce.com','2026-02-18 23:39:05',NULL,0,'plain','',0,0,'info');
INSERT INTO `SERVMASK_PREFIX_wc_admin_notes` VALUES (37,'woocommerce-WCReturnsWarranty-June-2023-updated-needed','update','en_US','Action required: Security update of WooCommerce Returns and Warranty Requests extension','<strong>Your store requires a security update for the Returns and Warranty Requests extension</strong>.  Please update to the latest version of the WooCommerce Returns and Warranty Requests extension immediately to address a potential vulnerability discovered on May 31.','{}','pending','woocommerce.com','2026-02-18 23:39:05',NULL,0,'plain','',0,0,'info');
INSERT INTO `SERVMASK_PREFIX_wc_admin_notes` VALUES (38,'woocommerce-WCOPC-June-2023-updated-needed','update','en_US','Action required: Security update of WooCommerce One Page Checkout','<strong>Your shop requires a security update to address a vulnerability in the WooCommerce One Page Checkout extension</strong>. The fix for this vulnerability was released for this extension on June 13th. Please update immediately.','{}','pending','woocommerce.com','2026-02-18 23:39:05',NULL,0,'plain','',0,0,'info');
INSERT INTO `SERVMASK_PREFIX_wc_admin_notes` VALUES (39,'woocommerce-WCGC-July-2023-update-needed','update','en_US','Action required: Security update of WooCommerce GoCardless Extension','<strong>Your shop requires a security update to address a vulnerability in the WooCommerce GoCardless extension</strong>. The fix for this vulnerability was released on July 4th. Please update immediately.','{}','pending','woocommerce.com','2026-02-18 23:39:05',NULL,0,'plain','',0,0,'info');
INSERT INTO `SERVMASK_PREFIX_wc_admin_notes` VALUES (40,'woocommerce-shipping-fedex-api-outage-2023-07-16','warning','en_US','Scheduled FedEx API outage — July 2023','On July 16 there will be a full outage of the FedEx API from 04:00 to 08:00 AM UTC. Due to planned maintenance by FedEx, you\'ll be unable to provide FedEx shipping rates during this time. Follow the link below for more information and recommendations on how to minimize impact.','{}','pending','woocommerce.com','2026-02-18 23:39:05',NULL,0,'plain','',0,0,'info');
INSERT INTO `SERVMASK_PREFIX_wc_admin_notes` VALUES (41,'wcship-2023-07-hazmat-update-needed','update','en_US','Action required: USPS HAZMAT compliance update for WooCommerce Shipping & Tax extension','<strong>Your store requires an update for the WooCommerce Shipping extension</strong>. Please update to the latest version of the WooCommerce Shipping &amp; Tax extension immediately to ensure compliance with new USPS HAZMAT rules currently in effect.','{}','pending','woocommerce.com','2026-02-18 23:39:05',NULL,0,'plain','',0,0,'info');
INSERT INTO `SERVMASK_PREFIX_wc_admin_notes` VALUES (42,'woocommerce-WCStripe-Aug-2023-update-needed','update','en_US','Action required: Security update for WooCommerce Stripe plugin','<strong>Your shop requires an important security update for the  WooCommerce Stripe plugin</strong>. The fix for this vulnerability was released on July 31. Please update immediately.','{}','pending','woocommerce.com','2026-02-18 23:39:05',NULL,0,'plain','',0,0,'info');
INSERT INTO `SERVMASK_PREFIX_wc_admin_notes` VALUES (43,'woocommerce-WCStripe-Aug-2023-security-updated','update','en_US','Security update of WooCommerce Stripe plugin','<strong>Your store has been updated to the latest secure version of the WooCommerce Stripe plugin</strong>. This update was released on July 31.','{}','pending','woocommerce.com','2026-02-18 23:39:05',NULL,0,'plain','',0,0,'info');
INSERT INTO `SERVMASK_PREFIX_wc_admin_notes` VALUES (44,'woocommerce-WooPayments-Aug-2023-security-updated','update','en_US','Security update of WooPayments (WooCommerce Payments) plugin','<strong>Your store has been updated to the more secure version of WooPayments (WooCommerce Payments)</strong>. This update was released on July 31.','{}','pending','woocommerce.com','2026-02-18 23:39:05',NULL,0,'plain','',0,0,'info');
INSERT INTO `SERVMASK_PREFIX_wc_admin_notes` VALUES (45,'avalara_q3-2023_noAvaTax','marketing','en_US','Automatically calculate VAT in real time','Take the effort out of determining tax rates and sell confidently across borders with automated tax management from Avalara AvaTax— including built-in VAT calculation when you sell into or across the EU and UK. Save time and stay compliant when you let Avalara do the heavy lifting.','{}','pending','woocommerce.com','2026-02-18 23:39:05',NULL,0,'plain','',0,0,'info');
INSERT INTO `SERVMASK_PREFIX_wc_admin_notes` VALUES (46,'woocommerce-usermeta-Sept2023-productvendors','update','en_US','Your store requires a security update','<strong>Your shop needs an update to address a vulnerability in WooCommerce.</strong> The fix was released on Sept 15. Please update WooCommerce to the latest version immediately. <a href=\"https://developer.woocommerce.com/2023/09/16/woocommerce-vulnerability-reintroduced-from-7-0-1/\" />Read our developer update</a> for more information.','{}','pending','woocommerce.com','2026-02-18 23:39:05',NULL,0,'plain','',0,0,'info');
INSERT INTO `SERVMASK_PREFIX_wc_admin_notes` VALUES (47,'woocommerce-STRIPE-Oct-2023-update-needed','update','en_US','Action required: Security update for WooCommerce Stripe Gateway','<strong>Your shop requires a security update to address a vulnerability in the WooCommerce Stripe Gateway</strong>. The fix for this vulnerability was released on October 17. Please update immediately.','{}','pending','woocommerce.com','2026-02-18 23:39:05',NULL,0,'plain','',0,0,'info');
INSERT INTO `SERVMASK_PREFIX_wc_admin_notes` VALUES (48,'amazon-mcf-reviews-2023-12-07','marketing','en_US','Enjoying Amazon MCF for WooCommerce?','We\'re Never Settle, the developers behind Amazon MCF for WooCommerce, and would be deeply honored to have your review. Reviews help immensely as other users can learn how MCF can solve their needs too! Not happy or need help? Please reach out for support and we’d love to make things right!','{}','pending','woocommerce.com','2026-02-18 23:39:05',NULL,0,'plain','',0,0,'info');
INSERT INTO `SERVMASK_PREFIX_wc_admin_notes` VALUES (49,'remove_estimated_deposits_2024','marketing','en_US','Estimated deposits are going away','To provide more accurate deposit information and support the expansion of instant deposits, estimated deposit details will no longer be available in WooPayments. We recommend upgrading to the latest version of WooPayments for more detailed balance status information.','{}','pending','woocommerce.com','2026-02-18 23:39:05',NULL,0,'plain','',0,0,'info');
INSERT INTO `SERVMASK_PREFIX_wc_admin_notes` VALUES (50,'sirt-woo-2024-11-xss-admin','update','en_US','An important update is required for WooCommerce','This update addresses a security vulnerability that could allow unauthorized access to administrative privileges on your site. <a href=\"https://developer.woocommerce.com/2024/12/03/woocommerce-9-4-3-and-woocommerce-9-3-4-available-now/\">Learn more</a>.\r\n<br><br>\r\n<strong>Please ensure your site is updated to the latest version to stay secure.</strong>','{}','pending','woocommerce.com','2026-02-18 23:39:05',NULL,0,'plain','',0,0,'info');
INSERT INTO `SERVMASK_PREFIX_wc_admin_notes` VALUES (51,'paypal-braintree-sdk-depreciation-2025-02-20','update','en_US','Update required for your PayPal Braintree extension','To continue securely accepting payments, you must update your PayPal Braintree extension to version 3.2.4 or newer before June 30, 2025. Your current extension version will not support payment processing after this date due to an SSL certificate update.','{}','pending','woocommerce.com','2026-02-18 23:39:05',NULL,0,'plain','',0,0,'info');
INSERT INTO `SERVMASK_PREFIX_wc_admin_notes` VALUES (52,'uk-vat-notice-2025-04-30','warning','en_US','UK VAT numbers are no longer supported','Due to recent HM Revenue &amp; Customs (HMRC) VAT API changes, your EU VAT Number for WooCommerce extension can no longer validate UK VAT numbers. HMRC now requires merchants to register an API key, which this extension does not currently support. We recommend EU/UK VAT Validation Manager for WooCommerce as a replacement','{}','pending','woocommerce.com','2026-02-18 23:39:05',NULL,0,'plain','',0,0,'info');
INSERT INTO `SERVMASK_PREFIX_wc_admin_notes` VALUES (53,'paypal-braintree-sdk-depreciation-2025-05-30','update','en_US','Action required: Update the PayPal Braintree extension','Your PayPal Braintree extension is using an outdated SDK and will stop processing payments after June 30, 2025, due to a root SSL certificate expiration. To avoid service disruption, update to version 3.2.4 or newer immediately.','{}','pending','woocommerce.com','2026-02-18 23:39:05',NULL,0,'plain','',0,0,'info');
INSERT INTO `SERVMASK_PREFIX_wc_admin_notes` VALUES (54,'paypal-carding-recaptcha-jan-26','update','en_US','Fraud protection is now required — enable today','Card networks like Visa and Mastercard now require fraud prevention controls, and non-compliance may result in fines and processing restrictions. Please enable reCAPTCHA in your PayPal Payments settings to help protect your store and maintain compliance.','{}','pending','woocommerce.com','2026-02-18 23:39:05',NULL,0,'plain','',0,0,'info');
INSERT INTO `SERVMASK_PREFIX_wc_admin_notes` VALUES (55,'wc-refund-returns-page','info','en_US','Setup a Refund and Returns Policy page to boost your store\'s credibility.','We have created a sample draft Refund and Returns Policy page for you. Please have a look and update it to fit your store.','{}','unactioned','woocommerce-core','2026-02-18 23:40:46',NULL,0,'plain','',0,0,'info');
INSERT INTO `SERVMASK_PREFIX_wc_admin_notes` VALUES (56,'wc-admin-mobile-app','info','en_US','Instala la aplicación móvil WooCommerce','Instala la aplicación móvil de WooCommerce para gestionar pedidos, recibir avisos de ventas y ver métricas clave – allí donde estés.','{}','unactioned','woocommerce-admin','2026-02-20 23:45:59',NULL,0,'plain','',0,0,'info');
INSERT INTO `SERVMASK_PREFIX_wc_admin_notes` VALUES (57,'wc-admin-onboarding-payments-reminder','info','en_US','¡Empieza a aceptar pagos en tu tienda!','Acepta pagos mediante el proveedor adecuado para ti - elige entre más de 100 pasarelas de pago para WooCommerce.','{}','unactioned','woocommerce-admin','2026-02-23 23:49:34',NULL,0,'plain','',0,0,'info');
INSERT INTO `SERVMASK_PREFIX_wc_admin_notes` VALUES (58,'wc-admin-usage-tracking-opt-in','info','en_US','Ayuda a WooCommerce a mejorar con el seguimiento de uso','Recopilar datos de uso nos permite mejorar WooCommerce. Se tendrá en cuenta a tu tienda a medida que evaluamos nuevas características, juzgamos la calidad de una actualización o determinamos si una mejora tiene sentido. Siempre puedes visitar los <a href=\"https://furbuddy.xyz/wp-admin/admin.php?page=wc-settings&#038;tab=advanced&#038;section=woocommerce_com\" target=\"_blank\">Ajustes</a> y elegir dejar de compartir datos. <a href=\"https://woocommerce.com/usage-tracking?utm_medium=product\" target=\"_blank\">Lee más</a> sobre los datos que recopilamos.','{}','unactioned','woocommerce-admin','2026-02-26 01:16:45',NULL,0,'plain','',0,1,'info');
INSERT INTO `SERVMASK_PREFIX_wc_admin_notes` VALUES (59,'Mailchimp-API-maintenance-feb-2026','update','en_US','Mailchimp Maintenance Feb 28','Mailchimp will be carrying out planned API maintenance on February 28 from 11am – 4pm EST. During that time, you may see brief sync interruptions in Mailchimp for WooCommerce. Most data will catch up automatically. See the <a href=\"https://developer.woocommerce.com/2026/02/27/mailchimp-api-maintenance-february-28/\" target=\"_blank\">Woo Developer blog</a> for more information.','{}','pending','woocommerce.com','2026-02-28 01:28:13',NULL,0,'plain','',0,0,'info');
INSERT INTO `SERVMASK_PREFIX_wc_admin_notes` VALUES (60,'RIN-WC-Security-Update-admin-update-March-2026','update','en_US','An important update is required for WooCommerce','<strong>Update to WooCommerce 10.5.3 or the latest version to resolve a security issue.</strong> This update addresses a vulnerability in WooCommerce versions 5.4 to 10.5.2 that could have permitted unauthorized admin account access. See the <a href=\"https://developer.woocommerce.com/2026/03/02/store-api-vulnerability-patched-in-woocommerce-5-4/\" target=\"_blank\">Woo Developer blog</a> for more information.','{}','pending','woocommerce.com','2026-03-03 03:57:49',NULL,0,'plain','',0,0,'info');
INSERT INTO `SERVMASK_PREFIX_wc_admin_notes` VALUES (62,'USPS_Scan_Form_Mar2026','marketing','en_US','New: Save time shipping with USPS SCAN Form','USPS SCAN Form consolidates multiple shipments into one scannable sheet. Hand off all your orders at once — no more scanning packages individually. Select “Create SCAN Form” under your orders to try it today.','{}','pending','woocommerce.com','2026-03-12 10:01:35',NULL,0,'plain','',0,0,'info');
INSERT INTO `SERVMASK_PREFIX_wc_admin_notes` VALUES (63,'wc-admin-launch-checklist','info','en_US','¿Estás preparado para lanzar tu tienda?','Para asegurarnos de que nunca tengas esa sensación de \"¿Qué se me olvidó?\" hemos preparado la lista de comprobación esencial de despegue.','{}','unactioned','woocommerce-admin','2026-03-19 20:35:14',NULL,0,'plain','',0,1,'info');
INSERT INTO `SERVMASK_PREFIX_wc_admin_notes` VALUES (64,'reddit_q1_2026','marketing','en_US','Start advertising on Reddit with a $500 bonus','Make the most of our new Reddit integration with $500 in Reddit Ads! For a limited time, new advertisers who spend $500 in Reddit Ads Manager over 30 days will get $500 in ad credit. Your bonus credit unlocks automatically when you hit $500 in spend. Use your credit within 30 days.','{}','pending','woocommerce.com','2026-03-28 04:45:14',NULL,0,'plain','',0,0,'info');
INSERT INTO `SERVMASK_PREFIX_wc_admin_notes` VALUES (65,'wc-admin-orders-milestone','info','en_US','¡Enhorabuena por haber procesado 10 pedidos!','¡Has logrado el hito de los 10 pedidos! Mira cómo vas. Ve algunas historias de éxito de WooCommerce para inspirarte.','{\"current_milestone\":10}','unactioned','woocommerce-admin','2026-04-08 16:38:51',NULL,0,'plain','',0,1,'info');
INSERT INTO `SERVMASK_PREFIX_wc_admin_notes` VALUES (66,'usps-surcharge-apr2026','marketing','en_US','Heads up: USPS rates increasing 8% on April 26','USPS is adding a temporary 8% surcharge on Priority Mail, Priority Mail Express, Ground Advantage, and Parcel Select from April 26, 2026 through January 17, 2027. WooCommerce Shipping discounted rates still apply.','{}','pending','woocommerce.com','2026-04-22 02:35:15',NULL,0,'plain','',0,0,'info');
INSERT INTO `SERVMASK_PREFIX_wc_admin_notes` VALUES (67,'stripe-woo-gateway-update-april2026','update','en_US','A critical update is required for Stripe for WooCommerce','<strong>A critical update is required for Stripe for WooCommerce</strong> that addresses possible payment issues. Please update the WooCommerce Stripe Gateway to v10.6.1 immediately.','{}','pending','woocommerce.com','2026-04-24 03:58:03',NULL,0,'plain','',0,0,'info');
INSERT INTO `SERVMASK_PREFIX_wc_admin_notes` VALUES (68,'klaviyo_q2_2026','marketing','en_US','Attn Woo: Klaviyo Customer Hub is here','Drive revenue and reduce your support burden by giving customers a single place to manage their orders, returns, subscriptions, loyalty, and more. Enable Customer Hub in your Klaviyo dashboard today, available on all paid plans.','{}','pending','woocommerce.com','2026-04-30 12:07:13',NULL,0,'plain','',0,0,'info');
INSERT INTO `SERVMASK_PREFIX_wc_admin_notes` VALUES (71,'wc-admin-new-sales-record','info','en_US','¡Nuevo récord de ventas!','¡Genial, 09/05/2026 ha sido tu día récord de ventas! Las ventas netas han sido de $1,022.25, superando el récord anterior de $867.74 establecido el 08/05/2026.','{\"old_record_date\":\"2026-05-08\",\"old_record_amt\":867.74,\"new_record_date\":\"2026-05-09\",\"new_record_amt\":1022.25}','unactioned','woocommerce-admin','2026-05-10 15:46:02',NULL,0,'plain','',0,0,'info');
INSERT INTO `SERVMASK_PREFIX_wc_admin_notes` VALUES (72,'existing_square_discountcodes_gtm_q2_2026','marketing','en_US','Automatic coupon sync now available in Square','The discount codes you create in your Square dashboard will now work directly on your WooCommerce checkout — no need to manually sync coupons. Manage all of your discounts from one place with automatic redemption count updates.','{}','pending','woocommerce.com','2026-05-14 17:21:09',NULL,0,'plain','',0,0,'info');
INSERT INTO `SERVMASK_PREFIX_wc_admin_notes` VALUES (73,'prospects_square_discountcodes_gtm_q2_2026','marketing','en_US','Square now offers automatic coupon sync','Big news for smoother cross-channel sales: you can now create discount codes in Square and have them work directly at checkout on your Woo store, no manual sync required. Save time when you manage your discounts from one place — and keep your online and in-person sales seamlessly connected.','{}','pending','woocommerce.com','2026-05-18 20:46:39',NULL,0,'plain','',0,0,'info');
INSERT INTO `SERVMASK_PREFIX_wc_admin_notes` VALUES (74,'wc-admin-real-time-order-alerts','info','en_US','Recibe alertas de pedidos en tiempo real en cualquier lugar','Recibe avisos sobre la actividad de la tienda, incluidos nuevos pedidos y reseñas de productos directamente en tus dispositivos móviles con la aplicación Woo.','{}','unactioned','woocommerce-admin','2026-05-20 22:02:18',NULL,0,'plain','',0,0,'info');
INSERT INTO `SERVMASK_PREFIX_wc_admin_notes` VALUES (75,'paypal_bnpl_mx_promo_Q2_2026','marketing','en_US','Bigger carts, lower fees: enable installments today','Merchants using PayPal installments see up to 205% higher average order values. Activate 3-installment payments from your PayPal Business dashboard and get 30% off transaction fees for 90 days. Sign up by October 15, 2026. Limited availability. Terms apply.','{}','pending','woocommerce.com','2026-05-20 22:02:19',NULL,0,'plain','',0,0,'info');
INSERT INTO `SERVMASK_PREFIX_wc_admin_notes` VALUES (76,'stripe_adaptivepricing_q2_2026','marketing','en_US','Sell internationally with Adaptive Pricing from Stripe','Adaptive Pricing is now available in the official Stripe for WooCommerce extension. Show prices in local currency across 150+ countries, lifting cross-border revenue by 17.8%. Shoppers pay exactly what they see at checkout, while you settle in your base currency.','{}','pending','woocommerce.com','2026-05-28 17:12:26',NULL,0,'plain','',0,0,'info');
INSERT INTO `SERVMASK_PREFIX_wc_admin_notes` VALUES (77,'woo-dotcom-course-2026-06-09','marketing','en_US','Learn how to build your store with WooCommerce','In this free course, we\'ll help you set up and run your online store with clear, practical guidance.','{}','pending','woocommerce.com','2026-06-10 03:38:25',NULL,0,'plain','',0,0,'info');
INSERT INTO `SERVMASK_PREFIX_wc_admin_notes` VALUES (78,'googleforwoocommerce_q2_2026','marketing','en_US','Limited-time offer: Get 2x your ad spend back in Google Ads','New to Google Ads and based in the US? Launch your first Google Ads campaign before June 30 to receive double your ad spend back as Google Ads credit.  \r\n\r\nUse new GenAI tools, YouTube Shopping, and Performance Max campaigns to sell more with WooCommerce and Google — get started today.','{}','pending','woocommerce.com','2026-06-13 10:42:58',NULL,0,'plain','',0,0,'info');
INSERT INTO `SERVMASK_PREFIX_wc_admin_notes` VALUES (79,'APFS-consolidation-jun-26','marketing','en_US','New features in WooCommerce Subscriptions','All Products for WooCommerce Subscriptions is now included in WooCommerce Subscriptions — no extra extension required. Create multiple plans for a single product and turn one-time purchases into recurring revenue. Update Subscriptions to version 9.0 to get started.','{}','pending','woocommerce.com','2026-06-23 17:19:00',NULL,0,'plain','',0,0,'info');
INSERT INTO `SERVMASK_PREFIX_wc_admin_notes` VALUES (80,'paypal_q3_2026','marketing','en_US','Important update to your Braintree integration','PayPal Enterprise Payments (formerly Braintree) is now officially owned by Woo. This change brings UI improvements, a long-term roadmap, and active updates from the Woo team, with guaranteed compatibility so your payments never miss a beat.','{}','pending','woocommerce.com','2026-07-09 04:34:17',NULL,0,'plain','',0,0,'info');
INSERT INTO `SERVMASK_PREFIX_wc_admin_notes` VALUES (81,'stripe-woo-gateway-update-july2026','update','en_US','An important update is required for Stripe for WooCommerce','<strong>A critical update is required for Stripe for WooCommerce</strong> to address an issue that could lead to fraudulent payment totals. Please update your extension to the latest version immediately.','{}','pending','woocommerce.com','2026-07-15 09:13:38',NULL,0,'plain','',0,0,'info');
INSERT INTO `SERVMASK_PREFIX_wc_admin_notes` VALUES (82,'usps-hazmat-Wcs-jul','marketing','en_US','USPS HAZMAT enforcement starts July 12','If you ship hazardous materials — lithium batteries, aerosols, perfume, paint — USPS adds noncompliance fees starting July 12. WooCommerce Shipping labels stay the same. Declare HAZMAT accurately, remove old HAZMAT marks from reused boxes, and place labels on the address side.','{}','pending','woocommerce.com','2026-07-15 09:13:38',NULL,0,'plain','',0,0,'info');
INSERT INTO `SERVMASK_PREFIX_wc_admin_notes` VALUES (83,'3pdmigration_paytrace_fortis','marketing','en_US','Important update about your Paytrace Gateway','Paytrace Gateway is being phased out of the WooCommerce.com Marketplace. Nothing changes right now, and your store will continue to work as usual. You’ll receive a retirement notice closer to the date. When you\'re ready to migrate, we recommend Fortis Payments — their team offers step-by-step migration guidance to help','{}','pending','woocommerce.com','2026-07-16 10:42:59',NULL,0,'plain','',0,0,'info');
INSERT INTO `SERVMASK_PREFIX_wc_admin_notes` VALUES (84,'3pdmigration_paytrace_visa','marketing','en_US','Important update about your Paytrace Gateway','Paytrace Gateway is being phased out of the WooCommerce.com Marketplace. Nothing changes right now, and your store will continue to work as usual. You’ll receive a retirement notice closer to the date. As a replacement, we recommend Visa Acceptance Solutions — accept popular payment methods in 97% of territories.','{}','pending','woocommerce.com','2026-07-16 10:42:59',NULL,0,'plain','',0,0,'info');
INSERT INTO `SERVMASK_PREFIX_wc_admin_notes` VALUES (85,'googleforwoocommerce_q2_2026_row_incentive','marketing','en_US','Choose one of three Google Ads signup offers','New to Google Ads? Launch your first campaign and get a budget boost with one of three signup offers. Choose the offer that fits your monthly budget and start reaching more customers in more places. Offer for new advertisers only. Terms apply.','{}','pending','woocommerce.com','2026-07-22 17:58:01',NULL,0,'plain','',0,0,'info');
INSERT INTO `SERVMASK_PREFIX_wc_admin_notes` VALUES (86,'mollie_incentive_h2_2026_PL','marketing','en_US','Localize your checkout with Mollie Payments','Boost conversions with BLIK and Przelewy24, alongside Europe’s most popular options, with Mollie’s smooth and reliable checkout experience. Sign up today and process up to PLN 50 000 with 0% fees until December 31. Terms and conditions apply.','{}','pending','woocommerce.com','2026-07-22 17:58:01',NULL,0,'plain','',0,0,'info');
INSERT INTO `SERVMASK_PREFIX_wc_admin_notes` VALUES (87,'klaviyo_q3_2026','marketing','en_US','Attn Woo: Klaviyo Customer Hub is here','Drive revenue and reduce your support burden by giving customers a single place to manage their orders, returns, subscriptions, loyalty, and more. Enable Customer Hub in your Klaviyo dashboard today, available on all paid plans.','{}','pending','woocommerce.com','2026-07-29 23:04:22',NULL,0,'plain','',0,0,'info');
INSERT INTO `SERVMASK_PREFIX_wc_admin_notes` VALUES (88,'woo-subscriptions-update-august2026','update','en_US','Please update WooCommerce Subscriptions now','<strong>The latest version of WooCommerce Subscriptions includes important security updates.</strong> Please update immediately to ensure your store is protected.','{}','pending','woocommerce.com','2026-08-06 02:52:05',NULL,0,'plain','',0,0,'info');
INSERT INTO `SERVMASK_PREFIX_wc_admin_notes` VALUES (89,'woocommerce-stripe-update-aug2026','update','en_US','An important update is required for Stripe for WooCommerce','<strong>There is a critical security update available for Stripe for WooCommerce.</strong> Please update to the latest version immediately.','{}','pending','woocommerce.com','2026-08-07 04:39:47',NULL,0,'plain','',0,0,'info');
INSERT INTO `SERVMASK_PREFIX_wc_admin_notes` VALUES (90,'fedex-ga-launch-wcs-aug26','marketing','en_US','WooCommerce Shipping now supports FedEx services','You can now give customers the speed and convenience of FedEx right from your store dashboard — with no minimum volume requirements. Offer popular domestic and international options, access discounted rates, and simplify your workflow when you ship FedEx on WooCommerce Shipping.','{}','pending','woocommerce.com','2026-08-07 04:39:47',NULL,0,'plain','',0,0,'info');
INSERT INTO `SERVMASK_PREFIX_wc_admin_notes` VALUES (91,'fedex-ga-wcst-aug26','marketing','en_US','WooCommerce Shipping now supports FedEx services','You can now give customers the speed and convenience of FedEx right from your store dashboard — with no minimum volume requirements. Offer popular domestic and international options, access discounted rates, and simplify your workflow when you ship FedEx on WooCommerce Shipping.','{}','pending','woocommerce.com','2026-08-07 04:39:47',NULL,0,'plain','',0,0,'info');
INSERT INTO `SERVMASK_PREFIX_wc_admin_notes` VALUES (92,'wc-admin-manage-orders-on-the-go','info','en_US','Gestiona tus pedidos desde cualquier lugar','Busca pedidos, información de clientes y procesa reembolsos en un clic con la app de Woo.','{}','unactioned','woocommerce-admin','2026-08-18 18:00:11',NULL,0,'plain','',0,0,'info');
INSERT INTO `SERVMASK_PREFIX_wc_admin_notes` VALUES (93,'mollie_incentive_h2_2026_sweden','marketing','en_US','Localize your checkout with Mollie Payments','Sell more with Swish, Klarna, and Europe’s other most popular options, using Mollie’s smooth and reliable checkout experience. Sign up today and process up to SEK 50,000 with 0% fees until December 31. Terms and conditions apply.','{}','pending','woocommerce.com','2026-09-09 17:18:04',NULL,0,'plain','',0,0,'info');
