DROP TABLE IF EXISTS `SERVMASK_PREFIX_mailpoet_subscribers`;
CREATE TABLE `SERVMASK_PREFIX_mailpoet_subscribers` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
